(function(A){Object.assign(A.D,{"G4314":{"l":"πρός","o":700,"ar":"<f><o>πρός</o>،</f> حرف جر مع المضاف إليه ومع القابل ومع المنصوب. <s n=\"I.\">مع المضاف إليه، للحركة من مكان: <b>من جهة</b>، ومن ثَمَّ مجازيًا: <b>لمصلحة، لأجل</b>، <r v=\"Acts.27.34\"></r>.</s> <s n=\"II.\">مع القابل، للقرب المكاني: <b>بجانب</b>، <b>قرب</b>، <b>عند</b>: <r v=\"Mark.5.11\"></r>، <r v=\"Luke.19.37\"></r>، <r v=\"John.18.16\"></r> <r v=\"John.20.11\"></r>، <r v=\"John.20.12\"></r>، <r v=\"Rev.1.13\"></r>.</s> <s n=\"III.\">مع المنصوب، للحركة أو الاتجاه نحو مكان أو شيء: <b>إلى</b>، <b>نحو</b>. <s n=\"1.\">للمكان، <s n=\"(a)\">بعد أفعال الحركة أو الكلام وألفاظ أخرى تتضمن معنى الاتجاه: <g>ἔρχομαι</g>، <g>ἀναβαίνω</g>، <g>πορεύομαι</g>، <g>λέγω</g>، <g>ἐπιστολή</g>، إلخ، <r v=\"Matt.3.14\"></r>، <r v=\"Mark.6.51\"></r>، <r v=\"Luke.11.5\"></r>، <r v=\"John.2.3\"></r>، <r v=\"Acts.9.2\"></r>، وفي مواضع أخرى كثيرة؛ مجازيًا، عن اتجاه الذهن، عدائيًا كان أو غير ذلك، <r v=\"Luke.23.12\"></r>، <r v=\"John.6.52\"></r>، <r v=\"2Cor.7.4\"></r>، <r v=\"Eph.6.12\"></r>، <r v=\"Col.3.13\"></r>، وفي مواضع أخرى؛ عن العاقبة أو النهاية، <r v=\"Luke.14.32\"></r>، <r v=\"John.11.4\"></r>، وفي مواضع أخرى؛ عن الغرض، <r v=\"Matt.26.12\"></r>، <r v=\"Rom.3.26\"></r>، <r v=\"1Cor.6.5\"></r>، وفي مواضع أخرى؛ <g>πρὸς τό</g> مع المصدر، للدلالة على الغرض (لكي)، <r v=\"Matt.5.28\"></r>، <r v=\"Mark.13.22\"></r>، <r v=\"Eph.6.11\"></r>، <r v=\"1Thess.2.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">للقرب الشديد: <b>عند</b>، <b>بجانب</b>، <b>مع</b>: <r v=\"Matt.3.10\"></r>، <r v=\"Mark.11.4\"></r>، <r v=\"Luke.4.11\"></r>، <r v=\"Acts.3.2\"></r>، وفي مواضع أخرى؛ بعد <g>εἶναι</g>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.1.1\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">للزمان، <s n=\"(a)\"><b>نحو</b> (السبعينية: <r v=\"Gen.8.11\"></r>، وفي مواضع أخرى): <r v=\"Luke.24.29\"></r>؛</s> <s n=\"(b)\"><b>إلى، لمدة</b>: <g>πρὸς καιρόν</g> (إلى حين)، <r v=\"Luke.8.13\"></r>، <r v=\"1Cor.7.5\"></r>؛ <g>πρὸς ὥραν</g> (ساعةً)، <r v=\"John.5.35\"></r>، وفي مواضع أخرى؛ <g>πρὸς ὀλίγον</g> (قليلاً)، <r v=\"Jas.4.14\"></r>.</s> </s> <s n=\"3.\">للعلاقة، <s n=\"(a)\"><b>نحو</b>، <b>مع</b>: <r v=\"Rom.5.1\"></r>، <r v=\"2Cor.1.12\"></r>، <r v=\"Col.4.5\"></r>، <r v=\"1Thess.4.12\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\"><b>من جهة، بالنسبة إلى</b>: <r v=\"Matt.19.8\"></r>، <r v=\"Mark.12.12\"></r>، <r v=\"Rom.8.31\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\"><b>فيما يخص</b>، <b>لـ</b>: <r v=\"Matt.27.4\"></r>، <r v=\"John.21.22\"></r>، <r v=\"Rom.15.17\"></r>، <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>؛</s> <s n=\"(d)\"><b>بحسب</b>: <r v=\"Luke.12.47\"></r>، <r v=\"2Cor.5.10\"></r>، <r v=\"Gal.2.14\"></r>، <r v=\"Eph.3.4\"></r> <r v=\"Eph.4.14\"></r>؛</s> <s n=\"(e)\"><b>بالمقارنة مع، بالقياس إلى</b>: <r v=\"Rom.8.18\"></r>.</s> </s> </s> <s n=\"IV.\">في التركيب: <b>نحو</b> (<g>προσέρχομαι</g>)، <b>إلى</b> (<g>προσάγω</g>)، <b>ضد</b> (<g>προσκόπτω</g>)، <b>فضلاً عن، علاوة على</b> (<g>προσδαπανάω</g>).</s>","en":"<f><o>πρός</o>,</f> prep. c. gen., dat., acc. <s n=\"I.\">C. gen., of motion from a place, <b>from the side of</b>, hence metaph., <b>in the interests of</b>, <r v=\"Acts.27.34\"></r> (cf. Page, in l.).</s> <s n=\"II.\">C. dat., of local proximity, <b>hard by</b>, <b>near</b>, <b>at</b>: <r v=\"Mark.5.11\"></r>, <r v=\"Luke.19.37\"></r>, <r v=\"John.18.16\"></r> <r v=\"John.20.11\"></r>, <r v=\"John.20.12\"></r>, <r v=\"Rev.1.13\"></r>.</s> <s n=\"III.\">C. acc., of motion or direction towards a place or object, <b>to</b>, <b>towards</b>. <s n=\"1.\">Of place, <s n=\"(a)\">after verbs of motion or of speaking and other words with the idea of direction: <g>ἔρχομαι</g>, <g>ἀναβαίνω</g>, <g>πορεύομαι</g>, <g>λέγω</g>, <g>ἐπιστολή</g>, etc., <r v=\"Matt.3.14\"></r>, <r v=\"Mark.6.51\"></r>, <r v=\"Luke.11.5\"></r>, <r v=\"John.2.3\"></r>, <r v=\"Acts.9.2\"></r>, al. mult.; metaph., of mental direction, hostile or otherwise, <r v=\"Luke.23.12\"></r>, <r v=\"John.6.52\"></r>, <r v=\"2Cor.7.4\"></r>, <r v=\"Eph.6.12\"></r>, <r v=\"Col.3.13\"></r>, al.; of the issue or end, <r v=\"Luke.14.32\"></r>, <r v=\"John.11.4\"></r>, al.; of purpose, <r v=\"Matt.26.12\"></r>, <r v=\"Rom.3.26\"></r>, <r v=\"1Cor.6.5\"></r>, al.; <g>πρὸς τό</g>, c. inf., denoting purpose (cf. M, <i>Pr.</i>, 218, 220; Lft., <i>Notes</i>, 131), <r v=\"Matt.5.28\"></r>, <r v=\"Mark.13.22\"></r>, <r v=\"Eph.6.11\"></r>, <r v=\"1Thess.2.9\"></r>, al.;</s> <s n=\"(b)\">of close proximity, <b>at</b>, <g>by</g>, <b>with</b>: <r v=\"Matt.3.10\"></r>, <r v=\"Mark.11.4\"></r>, <r v=\"Luke.4.11\"></r>, <r v=\"Acts.3.2\"></r>, al.; after <g>εἶναι</g>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.1.1\"></r>, al.</s> </s> <s n=\"2.\">Of time, <s n=\"(a)\"><b>towards</b> (Plat., Xen., LXX: <r v=\"Gen.8.11\"></r>, al.): <r v=\"Luke.24.29\"></r>;</s> <s n=\"(b)\"><b>for</b>: <g>πρὸς καιρόν</g>, <r v=\"Luke.8.13\"></r>, <r v=\"1Cor.7.5\"></r>; <g>πρὸς ὥραν</g>, <r v=\"John.5.35\"></r>, al.; <g>πρὸς ὀλίγον</g>, <r v=\"Jas.4.14\"></r>.</s> </s> <s n=\"3.\">Of relation <s n=\"(a)\"><b>toward</b>, <b>with</b>: <r v=\"Rom.5.1\"></r>, <r v=\"2Cor.1.12\"></r>, <r v=\"Col.4.5\"></r>, <r v=\"1Thess.4.12\"></r>, al.;</s> <s n=\"(b)\"><b>with regard to</b>: <r v=\"Matt.19.8\"></r>, <r v=\"Mark.12.12\"></r>, <r v=\"Rom.8.31\"></r>, al.;</s> <s n=\"(c)\"><b>pertaining to</b>, <b>to</b>: <r v=\"Matt.27.4\"></r>, <r v=\"John.21.22\"></r>, <r v=\"Rom.15.17\"></r>, <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>;</s> <s n=\"(d)\"><b>according to</b>: <r v=\"Luke.12.47\"></r>, <r v=\"2Cor.5.10\"></r>, <r v=\"Gal.2.14\"></r>, <r v=\"Eph.3.4\"></r> <r v=\"Eph.4.14\"></r>;</s> <s n=\"(e)\"><b>in comparison with</b>: <r v=\"Rom.8.18\"></r>.</s> </s> </s> <s n=\"IV.\">In composition: <b>towards</b> (<g>προσέρχομαι</g>), <b>to</b> (<g>προσάγω</g>), <b>against</b> (<g>προσκόπτω</g>), <b>besides</b> (<g>προσδαπανάω</g>).</s>"},"G4359":{"l":"προσοφείλω","o":1,"ar":"<f>* <o>προσ-οφείλω</o>،</f> <s><b>يدين بشيء فوق ذلك</b>، <b>يكون مديونًا أيضًا</b>: <r v=\"Phlm.1.19\"></r>.†</s>","en":"<f>* <o>προσ-οφείλω</o>,</f> <s><b>to owe besides</b>: <r v=\"Phlm.1.19\"></r> (v. Field, <i>Notes</i>, 225).†</s>"},"G4335":{"l":"προσευχή","o":36,"ar":"<f>† <o>προσ-ευχή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>صلاة</b> إلى الله: <r v=\"Matt.17.21\"></r>، <r v=\"Matt.21.22\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.22.45\"></r>، <r v=\"Acts.3.1\"></r>، <r v=\"Acts.6.4\"></r>، <r v=\"Acts.10.31\"></r>، <r v=\"Rom.12.12\"></r>، <r v=\"1Cor.7.5\"></r>، <r v=\"Col.4.2\"></r>؛ في الجمع: <r v=\"Acts.2.42\"></r>، <r v=\"Acts.10.4\"></r>، <r v=\"Rom.1.10\"></r>، <r v=\"Eph.1.16\"></r>، <r v=\"Col.4.12\"></r>، <r v=\"1Thess.1.2\"></r>، <r v=\"Phlm.1.4\"></r>، <r v=\"Phlm.1.22\"></r>، <r v=\"1Pet.3.7\"></r>، <r v=\"1Pet.4.7\"></r>، <r v=\"Rev.5.8\"></r>، <r v=\"Rev.8.3\"></r>، <r v=\"Rev.8.4\"></r>؛ <g>οἶκος προσευχῆς</g>: <r v=\"Matt.21.13\"></r>، <r v=\"Mark.11.17\"></r>، <r v=\"Luke.19.46\"></r> (السبعينية)؛ <g>π. καὶ δέησις</g>: <r v=\"Eph.6.18\"></r>، <r v=\"Phil.4.6\"></r>؛ في الجمع: <r v=\"1Tim.2.1\"></r>، <r v=\"1Tim.5.5\"></r>؛ <g>ἡ π. τοῦ θεοῦ</g>: <b>الصلاة إلى الله</b> (قارن <r v=\"Wis.16.28\"></r>): <r v=\"Luke.6.12\"></r>؛ <g>πρὸς τ. θεόν</g> يليه <g>ὑπέρ</g>: <r v=\"Acts.12.5\"></r>؛ في الجمع: <r v=\"Rom.15.30\"></r>؛ على الطريقة العبرية، <g>προσευχῇ προσεύχεσθαι</g>: <r v=\"Jas.5.17\"></r> (<i>صلّى بلجاجة</i>).</s> <s n=\"2.\"><b>مكان صلاة</b>: عن المجمع (قارن <r v=\"3Macc.7.20\"></r>، بقراءة مختلفة)؛ عن مكان في الخلاء: <r v=\"Acts.16.13\"></r>، <r v=\"Acts.16.16\"></r>.†</s>","en":"<f>† <o>προσ-ευχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσεύχομαι</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8605\">תְּפִלָּה</h>;]</e> </et> <s n=\"1.\"><b>prayer</b> to God: <r v=\"Matt.17.21\"></r> (WH, R, txt., om.) <r v=\"Matt.21.22\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.22.45\"></r>, <r v=\"Acts.3.1\"></r> <r v=\"Acts.6.4\"></r> <r v=\"Acts.10.31\"></r>, <r v=\"Rom.12.12\"></r>, <r v=\"1Cor.7.5\"></r>, <r v=\"Col.4.2\"></r>; pl., <r v=\"Acts.2.42\"></r> <r v=\"Acts.10.4\"></r>, <r v=\"Rom.1.10\"></r>, <r v=\"Eph.1.16\"></r>, <r v=\"Col.4.12\"></r>, <r v=\"1Thess.1.2\"></r>, <r v=\"Phlm.1.4\"></r>, <r v=\"Phlm.1.22\"></r>, <r v=\"1Pet.3.7\"></r> <r v=\"1Pet.4.7\"></r>, <r v=\"Rev.5.8\"></r> <r v=\"Rev.8.3\"></r>, <r v=\"Rev.8.4\"></r>; <g>οἶκος προσευχῆς</g>, <r v=\"Matt.21.13\"></r>, <r v=\"Mark.11.17\"></r>, <r v=\"Luke.19.46\"></r> (LXX); <g>π. καὶ δέησις</g>, <r v=\"Eph.6.18\"></r>, <r v=\"Phil.4.6\"></r>; pl., <r v=\"1Tim.2.1\"></r> <r v=\"1Tim.5.5\"></r>; <g>ἡ π. τοῦ θεοῦ</g>, <b>prayer to God</b> (cf. <r v=\"Wis.16.28\"></r>), <r v=\"Luke.6.12\"></r>; <g>πρὸς τ. θεόν</g>, seq. <g>ὑπέρ</g>, <r v=\"Acts.12.5\"></r>; pl., <r v=\"Rom.15.30\"></r>; Hebraistically (Bl., § 38, 3), <g>προσευχῇ προσεύχεσθαι</g>, <r v=\"Jas.5.17\"></r> (EV, <i>prayed fervently</i>).</s> <s n=\"2.\"><b>a place of prayer</b>: of a synagogue (<r v=\"3Macc.7.20\"></r>, v.l.; v. Charles, <i>APOT</i>, i, 173; for other exx., v. Kennedy, <i>Sources</i>, 114); of a place in the open (FlJ, <i>Ant.</i>, xiv, 10, 23), <r v=\"Acts.16.13\"></r>, <r v=\"Acts.16.16\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>δέησις</g>.</sy>"},"G4355":{"l":"προσλαμβάνω","o":12,"ar":"<f><o>προσ-λαμβάνω</o>،</f> <s n=\"1.\"><b>أخذ زيادةً، أضاف</b>.</s> <s n=\"2.\"><b>أخذ إليه</b>، <b>أخذ</b>، <b>قَبِل</b>؛ وهو في العهد الجديد دائمًا بالصيغة الوسطى، <g>-ομαι</g>؛ <s n=\"(a)\">عن الأشياء: عن الطعام، مع المنصوب: <r v=\"Acts.27.33\"></r>؛ مع المضاف إليه التبعيضي: <r v=\"Acts.27.36\"></r>؛</s> <s n=\"(b)\">عن الأشخاص: مع المنصوب: <r v=\"Matt.16.22\"></r>، <r v=\"Mark.8.32\"></r>، <r v=\"Acts.17.5\"></r>، <r v=\"Acts.18.26\"></r>، <r v=\"Acts.28.2\"></r>، <r v=\"Rom.14.1\"></r>، <r v=\"Rom.14.3\"></r>، <r v=\"Rom.15.7\"></r>، <r v=\"Phlm.1.17\"></r>.†</s> </s>","en":"<f><o>προσ-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.18.16\"></r> (<h n=\"H4871\">משׁה</h> hi.), <r v=\"Ps.73.24\"></r> (<h n=\"H3947\">לקח</h>), etc.;]</e> </et> <s n=\"1.\"><b>to take in addition</b>.</s> <s n=\"2.\"><b>to take to oneself</b>, <b>take</b>, <b>receive</b>; in NT always mid., <g>-ομαι</g>; <s n=\"(a)\">of things: of food, c. acc., <r v=\"Acts.27.33\"></r>; c. gen. part., <r v=\"Acts.27.36\"></r>;</s> <s n=\"(b)\">of persons: c. acc., <r v=\"Matt.16.22\"></r>, <r v=\"Mark.8.32\"></r> (v. Swete, in l.), <r v=\"Acts.17.5\"></r> <r v=\"Acts.18.26\"></r> <r v=\"Acts.28.2\"></r>, <r v=\"Rom.14.1\"></r>, <r v=\"Rom.14.3\"></r> <r v=\"Rom.15.7\"></r>, <r v=\"Phlm.1.17\"></r>.†</s> </s>"},"G4336":{"l":"προσεύχομαι","o":85,"ar":"<f><o>προσ-εύχομαι</o>،</f> <s><b>يصلّي</b> (دائمًا عن الصلاة إلى الله): مطلقًا، <r v=\"Matt.6.5-Matt.6.7\"></r>، <r v=\"Matt.6.9\"></r> <r v=\"Matt.14.23\"></r> <r v=\"Matt.19.13\"></r> <r v=\"Matt.26.36\"></r>، <r v=\"Matt.26.39\"></r>، <r v=\"Matt.26.41\"></r>، <r v=\"Matt.26.44\"></r>، <r v=\"Mark.1.35\"></r> <r v=\"Mark.6.46\"></r> <r v=\"Mark.11.24\"></r>، <r v=\"Mark.11.25\"></r> <r v=\"Mark.13.33\"></r> <r v=\"Mark.14.32\"></r>، <r v=\"Mark.14.38\"></r>، <r v=\"Mark.14.39\"></r>، <r v=\"Luke.1.10\"></r> <r v=\"Luke.3.21\"></r> <r v=\"Luke.5.16\"></r> <r v=\"Luke.6.12\"></r> <r v=\"Luke.9.18\"></r>، <r v=\"Luke.9.28\"></r>، <r v=\"Luke.9.29\"></r> <r v=\"Luke.11.1\"></r>، <r v=\"Luke.11.2\"></r> <r v=\"Luke.18.1\"></r>، <r v=\"Luke.18.10\"></r> <r v=\"Luke.22.44\"></r>، <r v=\"Acts.1.24\"></r> <r v=\"Acts.6.6\"></r> <r v=\"Acts.9.11\"></r>، <r v=\"Acts.9:40\"></r> <r v=\"Acts.10.9\"></r>، <r v=\"Acts.10.30\"></r> <r v=\"Acts.11.5\"></r> <r v=\"Acts.12.12\"></r> <r v=\"Acts.13.3\"></r> <r v=\"Acts.14.23\"></r> <r v=\"Acts.16.25\"></r> <r v=\"Acts.20.36\"></r> <r v=\"Acts.21.5\"></r> <r v=\"Acts.22.17\"></r> <r v=\"Acts.28.8\"></r>، <r v=\"1Cor.11.4\"></r>، <r v=\"1Cor.11.5\"></r> <r v=\"1Cor.14.14\"></r>، <r v=\"1Thess.5.17\"></r>، <r v=\"1Tim.2.8\"></r>، <r v=\"Jas.5.13\"></r>، <r v=\"Jas.5.18\"></r>؛ يليه <g>λέγων</g>، <r v=\"Matt.26.39\"></r>، <r v=\"Matt.26.42\"></r>، <r v=\"Luke.22.41\"></r>؛ مع القابل للأداة، <r v=\"1Cor.11.5\"></r> <r v=\"1Cor.14.14\"></r>، <r v=\"1Cor.14.15\"></r>؛ <g>μακρά</g>، <r v=\"Matt.23.14\"></r>، <r v=\"Mark.12.40\"></r>، <r v=\"Luke.20.47\"></r>؛ <g>ἐν πνεύματι</g> (<g>ἁγίῳ</g>)، <r v=\"Eph.6.18\"></r>، <r v=\"Jude.1.20\"></r>؛ <g>προσευχῇ π.</g> (أسلوب عبري، انظر تحت مدخل <g>προσευχή</g>)، <r v=\"Jas.5.17\"></r>؛ مع المنصوب للشيء، <r v=\"Luke.18.11\"></r>، <r v=\"Rom.8.26\"></r>؛ يليه <g>ἐπί</g> مع المنصوب للشخص، <r v=\"Jas.5.14\"></r>؛ مع القابل للشخص، <r v=\"Matt.6.6\"></r>، <r v=\"1Cor.11.13\"></r>؛ يليه <g>περί</g> مع المضاف إليه، <r v=\"Acts.8.15\"></r>، <r v=\"Col.1.3\"></r> <r v=\"Col.4.3\"></r>، <r v=\"1Thess.5.25\"></r>، <r v=\"2Thess.1.11\"></r> <r v=\"2Thess.3.1\"></r>، <r v=\"Heb.13.18\"></r>؛ <g>ὑπέρ</g>، <r v=\"Matt.5.44\"></r>، <r v=\"Luke.6.28\"></r>، <r v=\"Col.1.9\"></r>، <r v=\"Jas.5.16\"></r>؛ يليه <g>ἵνα</g>، <r v=\"Matt.24.20\"></r>، <r v=\"Mark.13.18\"></r> <r v=\"Mark.14.35\"></r>، <r v=\"Luke.22.46\"></r>، <r v=\"1Cor.14.13\"></r>؛ <g>τοῦτο ἵνα</g>، <r v=\"Phil.1.9\"></r>؛ مع المصدر، <r v=\"Luke.22.46\"></r>؛ يليه <g>τοῦ</g> مع المصدر، <r v=\"Jas.5.17\"></r>.†</s>","en":"<f><o>προσ-εύχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6419\">פלל</h> hith.;]</e> </et> <s><b>to pray</b> (always of prayer to God, or in cl., to gods): absol., <r v=\"Matt.6.5-Matt.6.7\"></r>, <r v=\"Matt.6.9\"></r> <r v=\"Matt.14.23\"></r> <r v=\"Matt.19.13\"></r> <r v=\"Matt.26.36\"></r>, <r v=\"Matt.26.39\"></r>, <r v=\"Matt.26.41\"></r>, <r v=\"Matt.26.44\"></r>, <r v=\"Mark.1.35\"></r> <r v=\"Mark.6.46\"></r> <r v=\"Mark.11.24\"></r>, <r v=\"Mark.11.25\"></r> <r v=\"Mark.13.33\"></r> (WH, R, txt., om.) <r v=\"Mark.14.32\"></r>, <r v=\"Mark.14.38\"></r>, <r v=\"Mark.14.39\"></r>, <r v=\"Luke.1.10\"></r> <r v=\"Luke.3.21\"></r> <r v=\"Luke.5.16\"></r> <r v=\"Luke.6.12\"></r> <r v=\"Luke.9.18\"></r>, <r v=\"Luke.9.28\"></r>, <r v=\"Luke.9.29\"></r> <r v=\"Luke.11.1\"></r>, <r v=\"Luke.11.2\"></r> <r v=\"Luke.18.1\"></r>, <r v=\"Luke.18.10\"></r> <r v=\"Luke.22.44\"></r> (WH, R, mg., om.), <r v=\"Acts.1.24\"></r> <r v=\"Acts.6.6\"></r> <r v=\"Acts.9.11\"></r>, <r v=\"Acts.9:40\"></r> <r v=\"Acts.10.9\"></r>, <r v=\"Acts.10.30\"></r> <r v=\"Acts.11.5\"></r> <r v=\"Acts.12.12\"></r> <r v=\"Acts.13.3\"></r> <r v=\"Acts.14.23\"></r> <r v=\"Acts.16.25\"></r> <r v=\"Acts.20.36\"></r> <r v=\"Acts.21.5\"></r> <r v=\"Acts.22.17\"></r> <r v=\"Acts.28.8\"></r>, <r v=\"1Cor.11.4\"></r>, <r v=\"1Cor.11.5\"></r> <r v=\"1Cor.14.14\"></r>, <r v=\"1Thess.5.17\"></r>, <r v=\"1Tim.2.8\"></r>, <r v=\"Jas.5.13\"></r>, <r v=\"Jas.5.18\"></r>; seq. <g>λέγων</g>, <r v=\"Matt.26.39\"></r>, <r v=\"Matt.26.42\"></r>, <r v=\"Luke.22.41\"></r>; c. dat. instr., <r v=\"1Cor.11.5\"></r> <r v=\"1Cor.14.14\"></r>, <r v=\"1Cor.14.15\"></r>; <g>μακρά</g>, <r v=\"Matt.23.14\"></r> (WH, R, txt., om.), <r v=\"Mark.12.40\"></r>, <r v=\"Luke.20.47\"></r>; <g>ἐν πνεύματι</g> (<g>ἁγίῳ</g>), <r v=\"Eph.6.18\"></r>, <r v=\"Jude.1.20\"></r>; <g>προσευχῇ π.</g> (a Hebraism, v.s. <g>προσευχή</g>), <r v=\"Jas.5.17\"></r>; c. acc. rei, <r v=\"Luke.18.11\"></r>, <r v=\"Rom.8.26\"></r>; seq. <g>ἐπί</g>, c. acc. pers., <r v=\"Jas.5.14\"></r>; c. dat. pers., <r v=\"Matt.6.6\"></r>, <r v=\"1Cor.11.13\"></r>; seq. <g>περί</g>, c. gen., <r v=\"Acts.8.15\"></r>, <r v=\"Col.1.3\"></r> <r v=\"Col.4.3\"></r>, <r v=\"1Thess.5.25\"></r>, <r v=\"2Thess.1.11\"></r> <r v=\"2Thess.3.1\"></r>, <r v=\"Heb.13.18\"></r>; <g>ὑπέρ</g>, <r v=\"Matt.5.44\"></r>, <r v=\"Luke.6.28\"></r>, <r v=\"Col.1.9\"></r>, <r v=\"Jas.5.16\"></r>; seq. <g>ἵνα</g>, <r v=\"Matt.24.20\"></r>, <r v=\"Mark.13.18\"></r> <r v=\"Mark.14.35\"></r>, <r v=\"Luke.22.46\"></r>, <r v=\"1Cor.14.13\"></r>; <g>τοῦτο ἵνα</g>, <r v=\"Phil.1.9\"></r>; c. inf., <r v=\"Luke.22.46\"></r>; seq. <g>τοῦ</g>, c. inf. (Bl., § 71, 3), <r v=\"Jas.5.17\"></r>.†</s>"},"G4396":{"l":"προφήτης","o":144,"ar":"<f><o>προφήτης</o>، <g>-ου, ὁ</g>،</f> <s>مَن يقوم بدور المفسِّر للمشيئة الإلهية أو المُعلِن لها، <b>نبي</b>؛ <s n=\"1.\">في اليونانية الكلاسيكية: عن مفسِّري الوحي (العرافات).</s> <s n=\"2.\">في العهد الجديد، <s n=\"(a)\">عن أنبياء العهد القديم: <r v=\"Matt.5.12\"></r>، <r v=\"Mark.6.15\"></r>، <r v=\"Luke.4.27\"></r>، <r v=\"John.8.52\"></r>، <r v=\"Rom.11.3\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">عن الأنبياء عمومًا: <r v=\"Matt.10.41\"></r> <r v=\"Matt.13.57\"></r> <r v=\"Matt.21.46\"></r>، <r v=\"Mark.6.4\"></r>، <r v=\"Luke.13.33\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">عن يوحنا المعمدان: <r v=\"Matt.21.26\"></r>، <r v=\"Mark.6.15\"></r>، <r v=\"Luke.1.76\"></r>؛</s> <s n=\"(d)\">عن المسيح: <r v=\"Matt.21.11\"></r>، <r v=\"John.6.14\"></r>، <r v=\"Acts.3.22\"></r>، <r v=\"Acts.3.23\"></r> <r v=\"Acts.7.37\"></r> (السبعينية)؛</s> <s n=\"(e)\">عن الأنبياء المسيحيين في العصر الرسولي: <r v=\"Acts.15.32\"></r>، <r v=\"1Cor.12.28\"></r>، <r v=\"Eph.2.20\"></r>، وفي مواضع أخرى؛</s> <s n=\"(f)\">كنايةً، عن كتابات الأنبياء: <r v=\"Luke.24.27\"></r>، <r v=\"Acts.8.28\"></r>، وفي مواضع أخرى؛</s> <s n=\"(g)\">عن شاعر: <r v=\"Titus.1.12\"></r>.</s> </s> </s>","en":"<f><o>προφήτης</o>, <g>-ου, ὁ</g> [&lt; <g>πρόφημι</g>, <i>to speak forth</i>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5030\">נָבִיא</h>;]</e> </et> <s>one who acts as an interpreter or forth-teller of the Divine will (v. Lft., <i>Notes</i>, 83 f.; Tr., <i>Syn.</i>, § vi), <b>a prophet</b>; <s n=\"1.\">in cl. (Æsch., Hdt., Plat., al.), of the interpreters of oracles.</s> <s n=\"2.\">In NT, <s n=\"(a)\">of the OT prophets: <r v=\"Matt.5.12\"></r>, <r v=\"Mark.6.15\"></r>, <r v=\"Luke.4.27\"></r>, <r v=\"John.8.52\"></r>, <r v=\"Rom.11.3\"></r>, al.;</s> <s n=\"(b)\">of prophets in general: <r v=\"Matt.10.41\"></r> <r v=\"Matt.13.57\"></r> <r v=\"Matt.21.46\"></r>, <r v=\"Mark.6.4\"></r>, <r v=\"Luke.13.33\"></r>, al.;</s> <s n=\"(c)\">of John the Baptist: <r v=\"Matt.21.26\"></r>, <r v=\"Mark.6.15\"></r>, <r v=\"Luke.1.76\"></r>;</s> <s n=\"(d)\">of Christ: <r v=\"Matt.21.11\"></r>, <r v=\"John.6.14\"></r>, <r v=\"Acts.3.22\"></r>, <r v=\"Acts.3.23\"></r> <r v=\"Acts.7.37\"></r> (LXX);</s> <s n=\"(e)\">of Christian prophets in the apostolic age: <r v=\"Acts.15.32\"></r>, <r v=\"1Cor.12.28\"></r>, <r v=\"Eph.2.20\"></r>, al.;</s> <s n=\"(f)\">by meton., of the writings of prophets: <r v=\"Luke.24.27\"></r>, <r v=\"Acts.8.28\"></r>, al.;</s> <s n=\"(g)\">of a poet: <r v=\"Titus.1.12\"></r> (on the use of the term in <g>π.</g> and Inscr., v. Deiss., <i>BS</i>, 235 f.; MM, xxii).</s> </s> </s>"},"G4387":{"l":"πρότερος","o":11,"ar":"<f>أ. صيغة التفضيل، <o>πρότερος</o>، <g>-α, -ον</g>،</f> <s><b>قبل، سابق</b>، عن الزمان والمكان والرتبة إلخ؛ وفي العهد الجديد دائمًا عن الزمان، <b>سابق</b>، <b>سالف (الأول)</b>: <r v=\"Eph.4.22\"></r>. وظرفيًا، <g>πρότερον</g>، <b>قبلاً</b>، <b>سابقًا</b>، <b>من قبل</b>: <r v=\"John.7.50\"></r>، <r v=\"2Cor.1.15\"></r>، <r v=\"Heb.4.6\"></r>؛ عكس <g>ἔπειτα</g>، <r v=\"Heb.7.27\"></r>؛ <g>τὸ π.</g>، <r v=\"John.6.62\"></r> <r v=\"John.9.8\"></r>، <r v=\"Gal.4.13\"></r>، <r v=\"1Tim.1.13\"></r>؛ <g>αἱ π. ἡμέραι</g>، <r v=\"Heb.10.32\"></r>؛ <g>αἱ π. ἐπιθυμίαι</g>، <r v=\"1Pet.1.14\"></r>.†</s>","en":"<f>A. Compar., <o>πρότερος</o>, <g>-α, -ον</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6440\">לִפָנִים</h>, <h n=\"H7223\">רִאשׁוֹן</h>, etc.;]</e> </et> <s><b>before</b>, of time, place, rank, etc.; in NT always of Time, <b>before</b>, <b>former</b>: <r v=\"Eph.4.22\"></r>. Adverbially, <g>πρότερον</g>, <b>before</b>, <b>aforetime</b>, <b>formerly</b>: <r v=\"John.7.50\"></r>, <r v=\"2Cor.1.15\"></r>, <r v=\"Heb.4.6\"></r>; opp. to <g>ἔπειτα</g>, <r v=\"Heb.7.27\"></r>; <g>τὸ π.</g>, <r v=\"John.6.62\"></r> <r v=\"John.9.8\"></r>, <r v=\"Gal.4.13\"></r>, <r v=\"1Tim.1.13\"></r>; <g>αἱ π. ἡμέραι</g>, <r v=\"Heb.10.32\"></r>; <g>αἱ π. ἐπιθυμίαι</g>, <r v=\"1Pet.1.14\"></r>.†</s>"},"G4318":{"l":"προσαγωγή","o":3,"ar":"<f>* <o>προσ-αγωγή</o>، <g>-ῆς, ἡ</g>،</f> <s n=\"1.\"><b>تقريب، إحضار إلى</b>.</s> <s n=\"2.\"><b>اقتراب</b>، <b>قدوم (دخول)</b>: <r v=\"Rom.5.2\"></r>، <r v=\"Eph.2.18\"></r> <r v=\"Eph.3.12\"></r>.†</s>","en":"<f>* <o>προσ-αγωγή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"derivation\">(&lt; <g>προσάγω</g>),</e> </et> <s n=\"1.\"><b>a bringing to</b>.</s> <s n=\"2.\"><b>approach</b>, <b>access</b> (v. Lft., <i>Notes</i>, 284; MM, xxi): <r v=\"Rom.5.2\"></r>, <r v=\"Eph.2.18\"></r> <r v=\"Eph.3.12\"></r> (but v. Ellic., <i>Eph.</i>, 59 f., where the transitive sense \"<i>introduction</i>\" is advocated).†</s>"},"G4376":{"l":"προσφορά","o":9,"ar":"<f><o>προσ-φορά</o>، <g>-ᾶς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تقديم</b>، <b>تقدمة</b>.</s> <s n=\"2.\">، <b>هدية</b>، <b>قربان (تقدمة)</b>؛ وفي العهد الجديد عن التقدمات الذبائحية: <r v=\"Acts.21.26\"></r> <r v=\"Acts.24.17\"></r>، <r v=\"Eph.5.2\"></r>، <r v=\"Heb.10.5\"></r>، <r v=\"Heb.10.8\"></r>، <r v=\"Heb.10.14\"></r>؛ <g>περί ἁμαρτίας</g>، <r v=\"Heb.10.18\"></r>؛ مع المضاف إليه المفعولي، <r v=\"Rom.15.16\"></r>، <r v=\"Heb.10.10\"></r>.†</s>","en":"<f><o>προσ-φορά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσφέρω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.7.48\"></r> (<h n=\"H6440\">פָּנִים</h>) <r v=\"Ps.40.6\"></r> (<h n=\"H4503\">מִנְחָה</h>), <r v=\"1Esd.5.52\"></r>, <r v=\"Sir.14.11\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a bringing to</b>, <b>offering</b> (Plat., al.).</s> <s n=\"2.\">(Less freq. in cl.), <b>a present</b>, <b>an offering</b>; in NT, of sacrificial offerings: <r v=\"Acts.21.26\"></r> <r v=\"Acts.24.17\"></r>, <r v=\"Eph.5.2\"></r>, <r v=\"Heb.10.5\"></r>, <r v=\"Heb.10.8\"></r>, <r v=\"Heb.10.14\"></r>; <g>περί ἁμαρτίας</g>, <r v=\"Heb.10.18\"></r>; c. gen. obj., <r v=\"Rom.15.16\"></r>, <r v=\"Heb.10.10\"></r>.†</s>"},"G4309":{"l":"προορίζω","o":5,"ar":"<f>*† <o>προ-ορίζω</o>،</f> <s><b>يحدِّد مسبقًا</b>، <b>يعيِّن سابقًا (سبق فعيَّن)</b>: مع المنصوب، <r v=\"Rom.8.30\"></r>؛ نفسه مع المصدر، <r v=\"Acts.4.28\"></r>؛ نفسه يليه <g>εἰς</g>، <r v=\"1Cor.2.7\"></r>، <r v=\"Eph.1.5\"></r>؛ مع مفعولين منصوبين، <r v=\"Rom.8.26\"></r>؛ المبني للمجهول، <r v=\"Eph.1.11\"></r>.†</s>","en":"<f>*† <o>προ-ορίζω</o>,</f> <s><b>to predetermine</b>, <b>foreordain</b>: c. acc., <r v=\"Rom.8.30\"></r>; id. et inf., <r v=\"Acts.4.28\"></r>; id. seq. <g>εἰς</g>, <r v=\"1Cor.2.7\"></r>, <r v=\"Eph.1.5\"></r>; c. dupl. acc., <r v=\"Rom.8.26\"></r>; pass., <r v=\"Eph.1.11\"></r>.†</s>"},"G4382":{"l":"προσωπολημψία","o":4,"ar":"<f>*† <o>προσωπολημψία</o>، <g>-ας, ἡ</g></f> <s><b>محاباة الوجوه (المحاباة)</b>: <r v=\"Rom.2.11\"></r>، <r v=\"Eph.6.9\"></r>، <r v=\"Col.3.25\"></r>، <r v=\"Jas.2.1\"></r>.†</s>","en":"<f>*† <o>προσωπολημψία</o> (Rec. <g>-ληψία</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσωπολήμπτης</g>),</e> </et> <s><b>respect of persons</b>: <r v=\"Rom.2.11\"></r>, <r v=\"Eph.6.9\"></r>, <r v=\"Col.3.25\"></r>, <r v=\"Jas.2.1\"></r> (v. Mayor, in l.).†</s>"},"G4343":{"l":"προσκαρτέρησις","o":1,"ar":"<f>*† <o>προσ-καρτέρησις</o>، <g>-εως, ἡ</g></f> <s><i>مواظبة</i>، <i>ثبات (مداومة)</i>: <r v=\"Eph.6.18\"></r>.†</s>","en":"<f>*† <o>προσ-καρτέρησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσκαρτερέω</g>),</e> </et> <s><i>stedfastness</i>, <i>perseverance</i>: <r v=\"Eph.6.18\"></r>.†</s>"},"G4388":{"l":"προτίθημι","o":3,"ar":"<f><o>προ-τίθημι</o>،</f> <s n=\"1.\"><b>يضع أمام</b>، <b>يعرض</b> علانيةً (يقدِّم)؛ وكذلك في الصيغة الوسطى: مع المنصوب للشخص، <r v=\"Rom.3.25\"></r> .</s> <s n=\"2.\">الصيغة الوسطى، <b>يضع أمام نفسه</b>، <b>يعتزم</b>، <b>يقصد</b>: مع المصدر، <r v=\"Rom.1.13\"></r>؛ مع المنصوب للشيء، <r v=\"Eph.1.9\"></r>.†</s>","en":"<f><o>προ-τίθημι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.40.4\"></r>, <r v=\"Exod.40.23\"></r>, <r v=\"Lev.24.8\"></r> (<h n=\"H6186\">ערךְ</h>) <r v=\"Ps.54.3\"></r> (<h n=\"H7760\">שׂוּם</h>), etc.;]</e> </et> <s n=\"1.\"><b>to set before</b>, <b>set forth</b> publicly; so also in mid.: c. acc. pers., <r v=\"Rom.3.25\"></r> (for a suggested alt. rend., v. MM, xxii).</s> <s n=\"2.\">Mid., <b>to set before oneself</b>, <b>propose</b>, <b>purpose</b>: c. inf., <r v=\"Rom.1.13\"></r>; c. acc. rei, <r v=\"Eph.1.9\"></r>.†</s>"},"G4347":{"l":"προσκλίνω","o":2,"ar":"<f>** <o>προσ-κλίνω</o>،</f> <s n=\"1.\"><b>يُسنِد إلى، يجعله يتّكئ على</b>.</s> <s n=\"2.\"><b>يجعل</b> كفة الميزان <b>تميل</b> إلى جهة أو أخرى؛ ومن ثمَّ مجازيًا عن الأشخاص، <b>يميل</b> (أي <g>ἑαυτόν</g>) <b>إلى</b>: المبني للمجهول، <r v=\"Acts.5.36\"></r>.†</s>","en":"<f>** <o>προσ-κλίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.14.24\"></r>*;]</e> </et> <s n=\"1.\"><b>to make to lean against</b>.</s> <s n=\"2.\"><b>to make</b> the scale <b>incline</b> one way or another; hence, metaph., of persons, <b>to incline</b> (sc. <g>ἑαυτόν</g>) <b>towards</b>: pass., <r v=\"Acts.5.36\"></r>.†</s>"},"G4327":{"l":"προσδέχομαι","o":14,"ar":"<f><o>προσ-δέχομαι</o>،</f> <s n=\"1.\"><b>يقبل إليه</b>، <b>يقبل بترحاب</b>، <b>يُدخل</b>، <b>يرتضي</b>: مع المنصوب للأشخاص، <r v=\"Luke.15.2\"></r>، <r v=\"Rom.16.2\"></r>، <r v=\"Phil.2.29\"></r>؛ مع المنصوب للأشياء، <r v=\"Acts.24.15\"></r>، <r v=\"Heb.10.34\"></r> <r v=\"Heb.11.35\"></r>.</s> <s n=\"2.\"><b>يتوقع</b>، <b>ينتظر</b>، <b>يترقّب</b>: مع المنصوب للأشخاص، <r v=\"Luke.12.36\"></r>؛ مع المنصوب للأشياء، <r v=\"Mark.15.43\"></r>، <r v=\"Luke.2.25\"></r>، <r v=\"Luke.2.38\"></r> <r v=\"Luke.23.51\"></r>، <r v=\"Acts.23.21\"></r>، <r v=\"Titus.2.13\"></r>، <r v=\"Jude.1.21\"></r> (قارن <g>δέχομαι</g>).†</s>","en":"<f><o>προσ-δέχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7521\">רצה</h>;]</e> </et> <s n=\"1.\"><b>to receive to oneself</b>, <b>receive favourably</b>, <b>admit</b>, <b>accept</b>: c. acc. pers., <r v=\"Luke.15.2\"></r>, <r v=\"Rom.16.2\"></r>, <r v=\"Phil.2.29\"></r>; c. acc. rei, <r v=\"Acts.24.15\"></r> (R, mg.), <r v=\"Heb.10.34\"></r> <r v=\"Heb.11.35\"></r>.</s> <s n=\"2.\"><b>to expect</b>, <b>look for</b>, <b>wait for</b>: c. acc. pers., <r v=\"Luke.12.36\"></r>; c. acc. rei, <r v=\"Mark.15.43\"></r>, <r v=\"Luke.2.25\"></r>, <r v=\"Luke.2.38\"></r> <r v=\"Luke.23.51\"></r>, <r v=\"Acts.23.21\"></r>, <r v=\"Titus.2.13\"></r>, <r v=\"Jude.1.21\"></r> (cf. <g>δέχομαι</g>).†</s>"},"G4392":{"l":"πρόφασις","o":6,"ar":"<f><o>πρό-φασις</o>، <g>-εως, ἡ</g></f> <s><b>ادِّعاء، تظاهُر</b>، <b>ذريعة، علّة</b>: <r v=\"Matt.23.1\"></r>، <r v=\"Mark.12.40\"></r>، <r v=\"Luke.20.47\"></r>، <r v=\"John.15.22\"></r>، <r v=\"Acts.27.30\"></r>، <r v=\"Phil.1.18\"></r>، <r v=\"1Thess.2.5\"></r>.†</s>","en":"<f><o>πρό-φασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>φήμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.141.4\"></r> (<h n=\"H5949\">עֲלִילָה</h>), <r v=\"Dan.6.4\"></r>, <r v=\"Dan.6.5\"></r> (<r v=\"Dan.6.5\"></r>, <r v=\"Dan.6.6\"></r>) (<h n=\"H5931\">עִלָּה</h>), <r v=\"Prov.18.1\"></r>, <r v=\"Hos.10.4\"></r>*;]</e> </et> <s><b>a pretence</b>, <b>pretext</b>: <r v=\"Matt.23.1\"></r> (WM, R, txt., om.), <r v=\"Mark.12.40\"></r>, <r v=\"Luke.20.47\"></r>, <r v=\"John.15.22\"></r>, <r v=\"Acts.27.30\"></r>, <r v=\"Phil.1.18\"></r>, <r v=\"1Thess.2.5\"></r>.†</s>"},"G4312":{"l":"προπετής","o":2,"ar":"<f><o>προπετής</o>، <g>-ές</g></f> <s><b>ساقط إلى الأمام</b>، <b>متهوِّر الاندفاع</b>. مجازيًا، <b>متسرِّع</b>، <b>طائش</b>، <b>متهوِّر</b>: عن الأشخاص، <r v=\"2Tim.3.4\"></r>؛ عن الأشياء، <r v=\"Acts.19.36\"></r>.†</s>","en":"<f><o>προπετής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>προπίπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.10.14\"></r> (<h n=\"H191\">אֱוִיל</h>) <r v=\"Prov.13.3\"></r> (<h n=\"H6589\">פֹּשׂק</h>) <r v=\"Sir.9.18\"></r>*;]</e> </et> <s><b>falling forwards</b>, <b>headlong</b>. Metaph., <b>precipitate</b>, <b>rash</b>, <b>reckless</b>: of persons, <r v=\"2Tim.3.4\"></r>; of things, <r v=\"Acts.19.36\"></r>.†</s>"},"G4395":{"l":"προφητεύω","o":28,"ar":"<f><o>προφητεύω</o></f> <s><b>يكون</b> <g>προφήτης</g> (انظره)، <b>يتنبأ</b>: بالمعنى الأصلي، أي إعلان مشورات الله، <r v=\"Matt.7.22\"></r>، <r v=\"Matt.26.68\"></r>، <r v=\"Mark.14.65\"></r>، <r v=\"Luke.1.67\"></r>، <r v=\"Luke.22.64\"></r>، <r v=\"Acts.19.6\"></r>، <r v=\"1Cor.11.4\"></r>، <r v=\"1Cor.11.5\"></r>، <r v=\"1Cor.13.9\"></r>، <r v=\"1Cor.14.1\"></r>، <r v=\"1Cor.14.3-1Cor.14.5\"></r>، <r v=\"1Cor.14.24\"></r>، <r v=\"1Cor.14.31\"></r>، <r v=\"1Cor.14.39\"></r>، <r v=\"Rev.11.3\"></r>؛ مع فكرة التنبؤ بالأحداث المستقبلة (وهي فكرة عرضية لا جوهرية)، <r v=\"Matt.11.13\"></r>، <r v=\"Acts.2.17\"></r>، <r v=\"Acts.2.18\"></r><i>(السبعينية)</i>، <r v=\"Acts.21.9\"></r>؛ يليه <g>περί</g>، <r v=\"Matt.15.7\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"1Pet.1.10\"></r>؛ <g>ἐπί</g> مع القابل، <r v=\"Rev.10.11\"></r>؛ <g>λέγων</g>، <r v=\"Jude.1.14\"></r>؛ <g>ὅτι</g>، <r v=\"John.11.51\"></r>.†</s>","en":"<f><o>προφητεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>προφήτης</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5012\">נבא</h> ni., hith.;]</e> </et> <s><b>to be a</b> <g>προφήτης</g> (q.v.), <b>to prophesy</b>: in the primary sense of telling forth the Divine counsels, <r v=\"Matt.7.22\"></r> <r v=\"Matt.26.68\"></r>, <r v=\"Mark.14.65\"></r>, <r v=\"Luke.1.67\"></r> <r v=\"Luke.22.64\"></r>, <r v=\"Acts.19.6\"></r>, <r v=\"1Cor.11.4\"></r>, <r v=\"1Cor.11.5\"></r> <r v=\"1Cor.13.9\"></r> <r v=\"1Cor.14.1\"></r>, <r v=\"1Cor.14.3-1Cor.14.5\"></r>, <r v=\"1Cor.14.24\"></r>, <r v=\"1Cor.14.31\"></r>, <r v=\"1Cor.14.39\"></r>, <r v=\"Rev.11.3\"></r>; with the idea of foretelling future events (an idea merely incidental, not essential; v. Lft., <i>Notes</i>, 83 f.), <r v=\"Matt.11.13\"></r>, <r v=\"Acts.2.17\"></r>, <r v=\"Acts.2.18\"></r><i>(LXX)</i> <r v=\"Acts.21.9\"></r>; seq. <g>περί</g>, <r v=\"Matt.15.7\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"1Pet.1.10\"></r>; <g>ἐπί</g>, c. dat., <r v=\"Rev.10.11\"></r>; <g>λέγων</g>, <r v=\"Jude.1.14\"></r>; <g>ὅτι</g>, <r v=\"John.11.51\"></r>.†</s> <sy><i>SYN.</i>: <g>μαντεύομαι</g>, q.v.</sy>"},"G4311":{"l":"προπέμπω","o":9,"ar":"<f>** <o>προ-πέμπω</o>،</f> <s n=\"1.\"><b>يرسل قدّامه</b>، <b>يبعث</b>.</s> <s n=\"2.\"><b>يشيّع</b> في سفر، <b>يرافق</b>: مع المنصوب للشخص، <r v=\"1Cor.16.11\"></r>، <r v=\"Titus.3.13\"></r>، <r v=\"3John.1.6\"></r>؛ يليه <g>εἰς</g>، <r v=\"Acts.20.38\"></r>؛ <g>οὗ</g>، <r v=\"1Cor.16.6\"></r>؛ <g>ἕως</g>، <r v=\"Acts.21.5\"></r>؛ المبني للمجهول، <r v=\"Acts.15.3\"></r>، <r v=\"Rom.15.24\"></r>، <r v=\"2Cor.1.16\"></r>.†</s>","en":"<f>** <o>προ-πέμπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.4.47\"></r>, <r v=\"Jdt.10.15\"></r>, <r v=\"Wis.19.2\"></r>, <r v=\"1Macc.12.4\"></r>, <r v=\"2Macc.6.23\"></r>*;]</e> </et> <s n=\"1.\"><b>to send before</b>, <b>send forth</b>.</s> <s n=\"2.\"><b>to set forward</b> on a journey, <b>escort</b>: c. acc. pers., <r v=\"1Cor.16.11\"></r>, <r v=\"Titus.3.13\"></r>, <r v=\"3John.1.6\"></r>; seq. <g>εἰς</g>, <r v=\"Acts.20.38\"></r>; <g>οὗ</g>, <r v=\"1Cor.16.6\"></r>; <g>ἕως</g>, <r v=\"Acts.21.5\"></r>; pass., <r v=\"Acts.15.3\"></r>, <r v=\"Rom.15.24\"></r>, <r v=\"2Cor.1.16\"></r>.†</s>"},"G4352":{"l":"προσκυνέω","o":60,"ar":"<f><o>προσ-κυνέω</o>، <g>-ῶ</g></f> <s><b>يسجد</b>، <b>يقدّم الإكرام لـ</b>، <b>يعبد</b>؛ <s n=\"(a)\">أصلاً (كما في الكلاسيكية عن الآلهة)، عن الله والمسيح والكائنات العلوية: مطلقًا، <r v=\"John.4.20\"></r> <r v=\"John.12.20\"></r>، <r v=\"Acts.8.27\"></r> <r v=\"Acts.24.11\"></r>، <r v=\"Heb.11.21\"></r>، <r v=\"Rev.11.1\"></r>؛ <g>πίπτειν καὶ π.</g>، <r v=\"Rev.5.14\"></r>؛ مع القابل، <r v=\"John.4.21\"></r>، <r v=\"John.4.23\"></r>، <r v=\"Acts.7.43\"></r>، <r v=\"1Cor.14.25\"></r>، <r v=\"Heb.1.6\"></r>، <r v=\"Rev.4.10\"></r> <r v=\"Rev.7.11\"></r> <r v=\"Rev.11.16\"></r> <r v=\"Rev.13.4\"></r>، <r v=\"Rev.13.15\"></r> <r v=\"Rev.14.7\"></r> <r v=\"Rev.16.2\"></r> <r v=\"Rev.19.4\"></r>، <r v=\"Rev.19.10\"></r>، <r v=\"Rev.19.20\"></r> <r v=\"Rev.22.8\"></r>، <r v=\"Rev.22.9\"></r>؛ مع المنصوب، <r v=\"Matt.4.10\"></r>، <r v=\"Luke.4.8\"></r> <r v=\"Luke.24.52\"></r>، <r v=\"John.4.22\"></r>، <r v=\"John.4.24\"></r>، <r v=\"Rev.9.20\"></r> <r v=\"Rev.13.4\"></r>، <r v=\"Rev.13.8\"></r>، <r v=\"Rev.13.12\"></r> <r v=\"Rev.14.9\"></r>، <r v=\"Rev.14.11\"></r> <r v=\"Rev.20.4\"></r>؛ يليه <g>ἐπώπιον</g>، <r v=\"Luke.4.7\"></r>، <r v=\"Rev.15.4\"></r>؛</s> <s n=\"(b)\">كما في الكلاسيكية، عن الإكرام لمن هم أعلى مقامًا من البشر: مطلقًا، <r v=\"Matt.20.20\"></r>، <r v=\"Acts.10.25\"></r>؛ مع القابل، <r v=\"Matt.2.2\"></r>، <r v=\"Matt.2.8\"></r> <r v=\"Matt.8.2\"></r> <r v=\"Matt.9.18\"></r> <r v=\"Matt.14.33\"></r> <r v=\"Matt.15.25\"></r> <r v=\"Matt.18.26\"></r> <r v=\"Matt.28.9\"></r>، <r v=\"Mark.15.19\"></r>، <r v=\"John.9.38\"></r>؛ <g>πεσὼν π.</g>، <r v=\"Matt.2.11\"></r> <r v=\"Matt.4.9\"></r>؛ <g>ἐνώπιον τ. ποδῶν</g>، <r v=\"Rev.3.9\"></r>؛ مع المنصوب، <r v=\"Mark.5.6\"></r>.†</s> </s>","en":"<f><o>προσ-κυνέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κυνέω</g>, <i>to kiss</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7812\">שׁחה</h> hith.;]</e> </et> <s><b>to make obeisance</b>, <b>do reverence to</b>, <b>worship</b>; <s n=\"(a)\">prop. (as in cl., of the gods: Hdt., Æsch., Plat., al.), of God, Christ and supra-mundane beings: absol., <r v=\"John.4.20\"></r> <r v=\"John.12.20\"></r>, <r v=\"Acts.8.27\"></r> <r v=\"Acts.24.11\"></r>, <r v=\"Heb.11.21\"></r> (Westc., in l.), <r v=\"Rev.11.1\"></r>; <g>πίπτειν καὶ π.</g>, <r v=\"Rev.5.14\"></r>; c. dat. (of the significance of this constr. as compared with the usual cl., c. acc., v. Abbott, <i>JG</i>, 78 f.; <i>JV</i>, 133 ff.), <r v=\"John.4.21\"></r>, <r v=\"John.4.23\"></r>, <r v=\"Acts.7.43\"></r>, <r v=\"1Cor.14.25\"></r>, <r v=\"Heb.1.6\"></r>, <r v=\"Rev.4.10\"></r> <r v=\"Rev.7.11\"></r> <r v=\"Rev.11.16\"></r> <r v=\"Rev.13.4\"></r>, <r v=\"Rev.13.15\"></r> <r v=\"Rev.14.7\"></r> <r v=\"Rev.16.2\"></r> <r v=\"Rev.19.4\"></r>, <r v=\"Rev.19.10\"></r>, <r v=\"Rev.19.20\"></r> <r v=\"Rev.22.8\"></r>, <r v=\"Rev.22.9\"></r>; c. acc. (v. supr.), <r v=\"Matt.4.10\"></r>, <r v=\"Luke.4.8\"></r> <r v=\"Luke.24.52\"></r> (WH, R, mg., om.), <r v=\"John.4.22\"></r>, <r v=\"John.4.24\"></r>, <r v=\"Rev.9.20\"></r> <r v=\"Rev.13.4\"></r>, <r v=\"Rev.13.8\"></r>, <r v=\"Rev.13.12\"></r> <r v=\"Rev.14.9\"></r>, <r v=\"Rev.14.11\"></r> <r v=\"Rev.20.4\"></r>; seq. <g>ἐπώπιον</g>, <r v=\"Luke.4.7\"></r>, <r v=\"Rev.15.4\"></r>;</s> <s n=\"(b)\">as in cl., of homage to human superiors (cf. MM, xxi): absol., <r v=\"Matt.20.20\"></r>, <r v=\"Acts.10.25\"></r>; c. dat. (v. supr.), <r v=\"Matt.2.2\"></r>, <r v=\"Matt.2.8\"></r> <r v=\"Matt.8.2\"></r> <r v=\"Matt.9.18\"></r> <r v=\"Matt.14.33\"></r> <r v=\"Matt.15.25\"></r> <r v=\"Matt.18.26\"></r> <r v=\"Matt.28.9\"></r>, <r v=\"Mark.15.19\"></r>, <r v=\"John.9.38\"></r>; <g>πεσὼν π.</g>, <r v=\"Matt.2.11\"></r> <r v=\"Matt.4.9\"></r>; <g>ἐνώπιον τ. ποδῶν</g>, <r v=\"Rev.3.9\"></r>; c. acc., <r v=\"Mark.5.6\"></r> (dat. T).†</s> </s>"},"G4350":{"l":"προσκόπτω","o":8,"ar":"<f><o>προσ-κόπτω</o>،</f> <s n=\"1.\">متعدٍّ: <b>صدم</b> (اليد أو الرجل مثلاً) <b>بـ</b>: مع المنصوب يليه <g>πρός</g>، مجازيًا: <r v=\"Matt.4.6\"></r>، <r v=\"Luke.4.11\"></r><i>(السبعينية)</i>.</s> <s n=\"2.\">لازم: <b>عثر</b>: مطلقًا (<r v=\"Tob.11.9\"></r>، <r v=\"Prov.3.23\"></r>): <r v=\"John.11.9\"></r>، <r v=\"John.11.10\"></r>؛ عن الريح: <b>هبّ على</b>، <b>صدم</b>: مع القابل: <r v=\"Matt.7.27\"></r>. مجازيًا، عند الكتّاب المتأخرين، <s n=\"(a)\"><b>أساء إلى</b>؛</s> <s n=\"(b)\"><b>عثر بـ</b>، <b>تعثّر في</b>: يليه <g>ἐν</g>: <r v=\"Rom.14.21\"></r>؛ مع القابل، <g>τ. λόγῳ</g>: <r v=\"1Pet.2.8\"></r>؛ <g>τ. λίθῳ τ. προσκόμματος</g>: <r v=\"Rom.9.32\"></r>.†</s> </s>","en":"<f><o>προσ-κόπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5062\">נגף</h>, <h n=\"H3782\">כּשׁל</h> ni., etc.;]</e> </et> <s n=\"1.\">trans., <b>to strike</b> (e.g. hand or foot) <b>against</b>: c. acc. seq. <g>πρός</g>, fig., <r v=\"Matt.4.6\"></r>, <r v=\"Luke.4.11\"></r><i>(LXX)</i>.</s> <s n=\"2.\">Intrans., <b>to stumble</b>: absol. (<r v=\"Tob.11.9\"></r>, <r v=\"Prov.3.23\"></r>), <r v=\"John.11.9\"></r>, <r v=\"John.11.10\"></r>; of wind, <b>to rush against</b>, <b>beat upon</b>: c. dat, <r v=\"Matt.7.27\"></r>. Metaph., in late writers, <s n=\"(a)\"><b>to offend</b> (Polyb.);</s> <s n=\"(b)\"><b>to take offence at</b>, <b>stumble at</b>: seq. <g>ἐν</g>, <r v=\"Rom.14.21\"></r>; c. dat., <g>τ. λόγῳ</g>, <r v=\"1Pet.2.8\"></r>; <g>τ. λίθῳ τ. προσκόμματος</g>, <r v=\"Rom.9.32\"></r>.†</s> </s>"},"G4308":{"l":"προοράω","o":5,"ar":"<f><o>προ-οράω</o>، <g>-ῶ</g>،</f> <s><b>رأى مُسبقًا (أمامه)</b> (من حيث المكان أو الزمان): مع المنصوب: <r v=\"Acts.21.29\"></r>. الصيغة الوسطى، مع المنصوب، يليه <g>ἐνώπιόν μου</g>: <r v=\"Acts.2.25\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>προ-οράω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.16.8\"></r>) (<h n=\"H7737\">שׁוה</h> pi.), <r v=\"1Esd.5.63\"></r> A*;]</e> </et> <s><b>to see before</b> (as to place or time): c. acc., <r v=\"Acts.21.29\"></r>. Mid., c. acc., seq. <g>ἐνώπιόν μου</g>, <r v=\"Acts.2.25\"></r><i>(LXX)</i>.†</s>"},"G4338":{"l":"προσηλόω","o":1,"ar":"<f>** <o>προσ-ηλόω</o>، <g>-ῶ</g>،</f> <s><b>سمّر في (بالمسامير)</b>: مع المنصوب والقابل، مجازيًا: <r v=\"Col.2.14\"></r>.†</s>","en":"<f>** <o>προσ-ηλόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.4.9\"></r>*;]</e> </et> <s><b>to nail to</b>: c. acc. et dat., fig., <r v=\"Col.2.14\"></r>.†</s>"},"G4337":{"l":"προσέχω","o":24,"ar":"<f><o>προσ-έχω</o>،</f> <s n=\"1.\"><b>وجّه إلى</b>، <b>أوصل إلى</b> (كثيرًا مع <g>ναῦν</g>، مذكورة أو مقدّرة: <i>أرسى السفينة</i>، <i>رسا على البرّ</i>).</s> <s n=\"2.\"><g>τ. νοῦν</g> يليه القابل: <b>وجّه ذهنه إلى</b>، <b>انتبه إلى</b>؛ وعند الكتّاب المتأخرين مع حذف <g>νοῦν</g>: <r v=\"Acts.8.6\"></r>، <r v=\"Acts.16.14\"></r>، <r v=\"Heb.2.1\"></r>، <r v=\"2Pet.1.19\"></r>؛ بمعنى الرعاية أو التدبير، <r v=\"Acts.20.28\"></r>؛ <g>π. ἑαυτῷ</g>: <b>احترز لنفسه</b> (قارن <r v=\"Gen.24.6\"></r>، <r v=\"Exod.10.28\"></r>، وفي مواضع أخرى): <r v=\"Luke.17.3\"></r>، <r v=\"Luke.21.34\"></r>، <r v=\"Acts.5.35\"></r>؛ وكذلك يليه <g>ἀπό</g> (انظر تحت مدخل <g>βλέπω</g>)، <r v=\"Luke.12.1\"></r>؛ (بدون قابل) <r v=\"Matt.7.15\"></r>، <r v=\"Matt.10.17\"></r>، <r v=\"Matt.16.6\"></r>، <r v=\"Matt.16.11\"></r>، <r v=\"Matt.16.12\"></r>، <r v=\"Luke.20.46\"></r> (قارن <r v=\"Sir.6.13\"></r>، وفي مواضع أخرى)؛ يليه <g>μή</g> مع المصدر، <r v=\"Matt.6.1\"></r>.</s> <s n=\"3.\"><b>لازم</b> أو <b>كرّس نفسه لـ</b>: مع قابل الشخص، <r v=\"Acts.8.10\"></r>، <r v=\"Acts.8.11\"></r>، <r v=\"1Tim.4.1\"></r>؛ مع قابل الشيء، <r v=\"1Tim.1.4\"></r>، <r v=\"1Tim.3.8\"></r>، <r v=\"1Tim.4.13\"></r>، <r v=\"1Tim.6.3\"></r>، <r v=\"Titus.1.14\"></r>، <r v=\"Heb.7.13\"></r>.†</s>","en":"<f><o>προσ-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7181\">קשׁב</h> hi., <h n=\"H8104\">שׁמר</h> ni., etc.;]</e> </et> <s n=\"1.\"><b>to turn to</b>, <b>bring to</b> (freq. <g>ναῦν</g>, expressed or understood, <i>to bring to port</i>, <i>land</i>; Hdt., al.).</s> <s n=\"2.\"><g>τ. νοῦν</g>, seq. dat., <b>to turn one's mind to</b>, <b>attend to</b>; in Xen. and later writers with <g>νοῦν</g> omitted (Bl., § 53, 1; 81, 1): <r v=\"Acts.8.6\"></r> <r v=\"Acts.16.14\"></r>, <r v=\"Heb.2.1\"></r>, <r v=\"2Pet.1.19\"></r>; in sense of caring or providing for, <r v=\"Acts.20.28\"></r>; <g>π. ἑαυτῷ</g>, <b>to give heed to oneself</b> (M, <i>Pr.</i>, 157; cf. <r v=\"Gen.24.6\"></r>, <r v=\"Exod.10.28\"></r>, al.): <r v=\"Luke.17.3\"></r> <r v=\"Luke.21.34\"></r>, <r v=\"Acts.5.35\"></r>; id. seq. <g>ἀπό</g> (M, <i>Pr.</i>, 102; Bl., § 34, 1<i>1</i>; 40, 3; v.s. <g>βλέπω</g>), <r v=\"Luke.12.1\"></r>; (without dat.) <r v=\"Matt.7.15\"></r> <r v=\"Matt.10.17\"></r> <r v=\"Matt.16.6\"></r>, <r v=\"Matt.16.11\"></r>, <r v=\"Matt.16.12\"></r>, <r v=\"Luke.20.46\"></r> (cf. <r v=\"Sir.6.13\"></r>, al.); seq. <g>μή</g>, c. inf. (M, <i>Pr.</i>, 193; Bl., § 69, 4), <r v=\"Matt.6.1\"></r>.</s> <s n=\"3.\"><b>to attach</b> or <b>devote oneself to</b>: c. dat. pers., <r v=\"Acts.8.10\"></r>, <r v=\"Acts.8.11\"></r>, <r v=\"1Tim.4.1\"></r>; c. dat. rei, <r v=\"1Tim.1.4\"></r> <r v=\"1Tim.3.8\"></r> <r v=\"1Tim.4.13\"></r> <r v=\"1Tim.6.3\"></r> T (<g>-ερχ-</g>, WH, R), <r v=\"Titus.1.14\"></r>, <r v=\"Heb.7.13\"></r>.†</s>"},"G4342":{"l":"προσκαρτερέω","o":10,"ar":"<f><o>προσ-καρτερέω</o>، <g>-ῶ</g></f> <s><b>واظب على</b>، <b>ثبت على</b>، <b>لازم</b>، <b>لبث في خدمة</b>: مع قابل الشخص، <r v=\"Mark.3.9\"></r>، <r v=\"Acts.8.13\"></r>، <r v=\"Acts.10.7\"></r>؛ مع قابل الشيء، <r v=\"Acts.1.14\"></r>، <r v=\"Acts.2.42\"></r>، <r v=\"Acts.6.4\"></r>، <r v=\"Rom.12.12\"></r>، <r v=\"Col.4.2\"></r>؛ يليه <g>ἐν</g>، <r v=\"Acts.2.46\"></r>؛ <g>εἰς</g>، <r v=\"Rom.13.6\"></r>.†</s>","en":"<f><o>προσ-καρτερέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>καρτερός</g>, <i>strong</i>, <i>stedfast</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.13.21\"></r> (<h n=\"H2388\">חזק</h> hith.), <r v=\"Tob.5.8\"></r> <h>א</h>, <r v=\"Sus.1.6\"></r>*;]</e> </et> <s><b>to attend constantly</b>, <b>continue stedfastly</b>, <b>adhere to</b>, <b>wait on</b>: c. dat. pers., <r v=\"Mark.3.9\"></r>, <r v=\"Acts.8.13\"></r> <r v=\"Acts.10.7\"></r>; c. dat. rei, <r v=\"Acts.1.14\"></r> <r v=\"Acts.2.42\"></r> <r v=\"Acts.6.4\"></r>, <r v=\"Rom.12.12\"></r>, <r v=\"Col.4.2\"></r>; seq. <g>ἐν</g>, <r v=\"Acts.2.46\"></r>; <g>εἰς</g>, <r v=\"Rom.13.6\"></r>.†</s>"},"G4322":{"l":"προσαναπληρόω","o":2,"ar":"<f>** <o>προσ-αναπληρόω</o>، <g>-ῶ</g>،</f> <s><b>سدّ النقص بالإضافة</b>، <b>وفّى تمامًا</b>: <r v=\"2Cor.9.12\"></r>، <r v=\"2Cor.11.9\"></r>.†</s>","en":"<f>** <o>προσ-αναπληρόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.19.4\"></r>*;]</e> </et> <s><b>to fill up by adding to</b>, <b>to supply fully</b>: <r v=\"2Cor.9.12\"></r> <r v=\"2Cor.11.9\"></r>.†</s>"},"G4340":{"l":"πρόσκαιρος","o":4,"ar":"<f>** <o>πρόσ-καιρος</o>، <g>-ον</g>،</f> <s n=\"1.\"><b>في حينه، في وقته</b>.</s> <s n=\"2.\"><b>إلى حين</b>، <b>وقتي، زمني</b>، <b>زائل</b>: <r v=\"2Cor.4.18\"></r>، <r v=\"Heb.11.25\"></r>؛ عن النباتات، <b>قصير العمر</b>: <r v=\"Matt.13.21\"></r>، <r v=\"Mark.4.17\"></r>.†</s>","en":"<f>** <o>πρόσ-καιρος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.15.2\"></r>, <r v=\"4Macc.15.8\"></r>, <r v=\"4Macc.15.23\"></r>*;]</e> </et> <s n=\"1.\"><b>in season</b>.</s> <s n=\"2.\"><b>for a season</b>, <b>temporary</b>, <b>transient</b>: <r v=\"2Cor.4.18\"></r>, <r v=\"Heb.11.25\"></r>; of plants, <b>short-lived</b>: <r v=\"Matt.13.21\"></r>, <r v=\"Mark.4.17\"></r>.†</s>"},"G4369":{"l":"προστίθημι","o":18,"ar":"<f><o>προσ-τίθημι</o>،</f> <s n=\"1.\"><b>وضع إلى جانب</b>.</s> <s n=\"2.\"><b>زاد</b>، <b>أضاف إلى</b>، <b>أعطى زيادةً</b>: مع المنصوب يليه <g>ἐπί</g>، <r v=\"Matt.6.27\"></r>، <r v=\"Luke.3.20\"></r> <r v=\"Luke.12.25\"></r>؛ <g>ἐπὶ τὸ αὐτό</g>، <r v=\"Acts.2.47\"></r>؛ مع المنصوب والقابل، <r v=\"Luke.17.5\"></r>، <r v=\"Heb.12.19\"></r>؛ المبني للمجهول، مطلقًا، <r v=\"Acts.2.41\"></r>، <r v=\"Gal.3.19\"></r>؛ مع القابل، <r v=\"Matt.6.33\"></r>، <r v=\"Mark.4.24\"></r>، <r v=\"Luke.12.31\"></r>، <r v=\"Acts.5.14\"></r> <r v=\"Acts.11.24\"></r>؛ <g>προσετέθη πρὸς τ. πατέρας</g> (قارن <r v=\"Gen.26.8\"></r>، <r v=\"Judg.2.10\"></r>، وفي مواضع أخرى)، <r v=\"Acts.13.36\"></r>؛ مع المصدر، للدلالة على تكرار الفعل الذي يدل عليه الفعل التالي أو استمراره، كما في الأسلوب العبري (<r v=\"Gen.4.2\"></r> <r v=\"Gen.8.12\"></r>، وفي مواضع أخرى)، <r v=\"Luke.20.11\"></r>، <r v=\"Acts.12.3\"></r>؛ وكذلك اسم الفاعل، <g>προσθείς</g>، مع الإخباري (<r v=\"Gen.38.5\"></r>، وفي مواضع أخرى)، <r v=\"Luke.19.11\"></r>.†</s>","en":"<f><o>προσ-τίθημι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3254\">יסף</h> hi., also for <h n=\"H622\">אסף</h> ni., etc.;]</e> </et> <s n=\"1.\"><b>to put to</b>.</s> <s n=\"2.\"><b>to add</b>, <b>join to</b>, <b>give in addition</b>: c. acc. seq. <g>ἐπί</g>, <r v=\"Matt.6.27\"></r>, <r v=\"Luke.3.20\"></r> <r v=\"Luke.12.25\"></r>; <g>ἐπὶ τὸ αὐτό</g>, <r v=\"Acts.2.47\"></r>; c. acc. et dat., <r v=\"Luke.17.5\"></r>, <r v=\"Heb.12.19\"></r> (v. MM, xxi); pass., absol., <r v=\"Acts.2.41\"></r>, <r v=\"Gal.3.19\"></r>; c. dat., <r v=\"Matt.6.33\"></r>, <r v=\"Mark.4.24\"></r>, <r v=\"Luke.12.31\"></r>, <r v=\"Acts.5.14\"></r> <r v=\"Acts.11.24\"></r>; <g>προσετέθη πρὸς τ. πατέρας</g> (cf. <r v=\"Gen.26.8\"></r>, <r v=\"Judg.2.10\"></r>, al.), <r v=\"Acts.13.36\"></r>; c. inf., of repeating or continuing the action signified by the following verb, as in Heb. idiom (<r v=\"Gen.4.2\"></r> <r v=\"Gen.8.12\"></r>, al.; cf. WM, § 54, 5; Lft. on Clem., <i>I Co.</i>, xii; but v. also M, <i>Pr.</i>, 67, 233; Deiss., <i>BS</i>, 67<i>1</i>; MM, xxi), <r v=\"Luke.20.11\"></r>, <r v=\"Acts.12.3\"></r>; similarly ptcp., <g>προσθείς</g>, c. indic. (<r v=\"Gen.38.5\"></r>, al.), <r v=\"Luke.19.11\"></r>.†</s>"},"G4323":{"l":"προσανατίθημι","o":2,"ar":"<f>* <o>προσ-ανα-τίθημι</o>،</f> <s><b>وضع على</b> أو <b>قدّم زيادةً</b>؛ الصيغة الوسطى، <s n=\"(a)\"><b>حمّل نفسه زيادةً</b>، <b>تعهّد بأمر آخر</b>؛</s> <s n=\"(b)\">مع المضاف إليه للشخص، عن إعطاء المعلومات أو طلبها: <b>استشار</b>، <b>أفضى إلى</b>: <r v=\"Gal.1.16\"></r> <r v=\"Gal.2.6\"></r> (قارن <g>ἀνα-τίθημι</g>).</s> </s>","en":"<f>* <o>προσ-ανα-τίθημι</o>,</f> <s><b>to lay on</b> or <b>offer besides</b>; mid., <s n=\"(a)\"><b>to lay on oneself in addition</b>, <b>undertake besides</b>;</s> <s n=\"(b)\">c. gen. pers., of giving or obtaining information, <b>to consult</b>, <b>communicate</b>: <r v=\"Gal.1.16\"></r> <r v=\"Gal.2.6\"></r> (Lft., in l.; cf. <g>ἀνα-τίθημι</g>).</s> </s>"},"G4346":{"l":"πρόσκλισις","o":1,"ar":"<f>*† <o>πρόσ-κλισις</o>، <g>-εως, ἡ</g></f> <s><b>ميل</b>، <b>محاباة</b>: <r v=\"1Tim.5.21\"></r>.†</s>","en":"<f>*† <o>πρόσ-κλισις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσκλίνω</g>),</e> </et> <s><b>inclination</b> <b>partiality</b>: <r v=\"1Tim.5.21\"></r>.†</s>"},"G4302":{"l":"προλέγω","o":15,"ar":"<f><o>προ-λέγω</o>،</f> <s n=\"1.\"><b>يُخبر</b> أو <b>يقول سابقًا</b>: <r v=\"2Cor.13.2\"></r>، <r v=\"Gal.5.21\"></r>، <r v=\"1Thess.3.4\"></r> (قارن <g>προεῖπον</g>، ولكن انظر أدناه).</s> <s n=\"2.\"><b>يُعلن</b>، <b>يقول صراحةً</b>: <r v=\"2Cor.13.2\"></r>، <r v=\"Gal.5.21\"></r>، <r v=\"1Thess.3.4\"></r> (قارن <r v=\"Isa.41.26\"></r>).†</s>","en":"<f><o>προ-λέγω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.41.26\"></r> (<h n=\"H5046\">נגד</h> hi.)*;]</e> </et> <s n=\"1.\"><b>to tell</b> or <b>say beforehand</b>: <r v=\"2Cor.13.2\"></r>, <r v=\"Gal.5.21\"></r>, <r v=\"1Thess.3.4\"></r> (R, txt.; cf. <g>προεῖπον</g>, but v. infr.).</s> <s n=\"2.\"><b>to declare</b>, <b>tell plainly</b>: <r v=\"2Cor.13.2\"></r>, <r v=\"Gal.5.21\"></r>, <r v=\"1Thess.3.4\"></r> (R, mg.; v. MM, xxi, and cf. <r v=\"Isa.41.26\"></r>).†</s>"},"G4307":{"l":"πρόνοια","o":2,"ar":"<f><o>πρόνοια</o>، <g>-ας, ἡ</g></f> <s><b>تدبير، بُعد نظر</b>: <r v=\"Acts.24.3\"></r>؛ <g>π. ποιεῖσθαι</g>، مع المضاف إليه: <b>يدبّر لـ</b>، <b>يعتني بـ</b>: <r v=\"Rom.13.14\"></r>.†</s>","en":"<f><o>πρόνοια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πρόνοος</g>, <i>careful</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.6.18\"></r> (<r v=\"Dan.6.19\"></r>) <r v=\"Wis.14.3\"></r> <r v=\"Wis.17.2\"></r>, II-IV Mac<i>6</i>*;]</e> </et> <s><b>foresight</b>, <b>forethought</b>: <r v=\"Acts.24.3\"></r>; <g>π. ποιεῖσθαι</g>, c. gen. (Dem., 546, 6), <b>make provision for</b>, <b>show care for</b>: <r v=\"Rom.13.14\"></r>.†</s>"},"G4349":{"l":"προσκοπή","o":1,"ar":"<f>** <o>προσκοπή</o>، <g>-ῆς, ἡ</g></f> <s><b>سبب عثرة</b>، <b>عثرة</b>: <r v=\"2Cor.6.3\"></r>.†</s>","en":"<f>** <o>προσκοπή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσκόπτω</g>),</e> <e t=\"septuagint\">[in Gr. Ven.: <r v=\"Prov.16.18\"></r> (<h n=\"H3783\">כִּשָּׁלוֹן</h>)*;]</e> </et> <s><b>an occasion of stumbling</b>, <b>offence</b>: <r v=\"2Cor.6.3\"></r>.†</s>"},"G4368":{"l":"προστάτις","o":1,"ar":"<f>* <o>προστάτις</o>، <g>-ιδος, ἡ</g></f> <s><b>مساعِدة</b>، <b>حامية، راعية</b>: <r v=\"Rom.16.2\"></r>.†</s>","en":"<f>* <o>προστάτις</o>, <g>-ιδος, ἡ</g></f> <et> <e t=\"derivation\">(fem. of <g>προστάτης</g>),</e> </et> <s><b>a patroness</b>, <b>protectress</b>: <r v=\"Rom.16.2\"></r>.†</s>"},"G4375":{"l":"προσφιλής","o":1,"ar":"<f>** <o>προσφιλής</o>، <g>-ές</g></f> <s n=\"(a)\">عن الأشخاص، بالمعنيين المعلوم والمجهول (مُحِبّ ومحبوب) (في السبعينية: <r v=\"Ezra.5.1\"></r>، <r v=\"Sir.4.7\"></r>، <r v=\"Sir.20.13\"></r>)؛</s> <s n=\"(b)\">عن الأشياء: <b>مُبهِج</b>، <b>مُستحَبّ</b>، <b>مُسِرّ</b>: <r v=\"Phil.4.8\"></r>.†</s>","en":"<f>** <o>προσφιλής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>φιλέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.5.1\"></r>, <r v=\"Sir.4.7\"></r> <r v=\"Sir.20.13\"></r>*;]</e> </et> <s n=\"(a)\">of persons, in both act. and pass. sense (LXX, <r v=\"Ezra.5.1\"></r>, <r v=\"Sir.4.7\"></r> <r v=\"Sir.20.13\"></r>);</s> <s n=\"(b)\">of things, <b>pleasing</b>, <b>agreeable</b> (EV, <i>lovely</i>): <r v=\"Phil.4.8\"></r>.†</s>"},"G4397":{"l":"προφητικός","o":2,"ar":"<f>*† <o>προφητικός</o>، <g>-ά, -όν</g></f> <s><b>نبوي</b>، <b>خاص بالنبوة</b>: <r v=\"Rom.16.26\"></r>، <r v=\"2Pet.1.19\"></r>.†</s>","en":"<f>*† <o>προφητικός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>προφήτης</g>),</e> </et> <s><b>of prophecy</b>, <b>prophetic</b>: <r v=\"Rom.16.26\"></r>, <r v=\"2Pet.1.19\"></r>.†</s>"},"G4300":{"l":"προκυρόω","o":1,"ar":"<f>*† <o>προ-κυρόω</o>، <g>-ῶ</g>،</f> <s><b>أثبت</b> أو <b>صادق على من قبل</b>: <r v=\"Gal.3.17\"></r>.†</s>","en":"<f>*† <o>προ-κυρόω</o>, <g>-ῶ</g>,</f> <s><b>to establish</b> or <b>confirm beforehand</b>: <r v=\"Gal.3.17\"></r>.†</s>"},"G4334":{"l":"προσέρχομαι","o":86,"ar":"<f><o>προσ-έρχομαι</o>،</f> <s><b>يتقدّم إلى</b>، <b>يقترب</b>: مطلقًا، <r v=\"Matt.4.11\"></r>، <r v=\"Luke.9.42\"></r>، وفي مواضع أخرى؛ مع المصدر، <r v=\"Matt.24.1\"></r>، وفي مواضع أخرى؛ مع القابل للمكان، <r v=\"Heb.12.18\"></r>، <r v=\"Heb.12.22\"></r>؛ مع القابل للشخص، <r v=\"Matt.5.1\"></r>، وكثيرًا، <r v=\"John.12.21\"></r>، وفي مواضع أخرى؛ اسم الفاعل، <g>προσελθών</g>، مع الإخباري، <r v=\"Matt.8.2\"></r>، وكثيرًا، <r v=\"Mark.1.31\"></r>، <r v=\"Luke.7.14\"></r>، وفي مواضع أخرى؛ <g>π. αὐτῷ</g>، مع الإخباري، <r v=\"Matt.4.3\"></r>، <r v=\"Mark.6.35\"></r>. مجازيًا، <s n=\"(a)\">عن التقدم إلى الله: مطلقًا (<r v=\"Lev.21.17\"></r>، <r v=\"Deut.21.5\"></r>، وفي مواضع أخرى)، <r v=\"Heb.10.1\"></r>، <r v=\"Heb.10.22\"></r>؛ <g>τ. θεῷ</g>، <r v=\"Heb.7.25\"></r> <r v=\"Heb.11.6\"></r>؛ <g>τ. θρόνῳ τ. χάριτος</g>، <r v=\"Heb.4.16\"></r>؛ <g>πρὸς Χριστόν</g>، <r v=\"1Pet.2.4\"></r>؛</s> <s n=\"(b)\">بمعنى لا يرد في موضع آخر: <b>يوافق على</b>: <g>ὑγιαίνουσι λόγοις</g>، <r v=\"1Tim.6.3\"></r>.</s> </s>","en":"<f><o>προσ-έρχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7126\">קרב</h>, <h n=\"H5066\">נגשׁ</h>, etc.;]</e> </et> <s><b>to approach</b>, <b>draw near</b>: absol., <r v=\"Matt.4.11\"></r>, <r v=\"Luke.9.42\"></r>, al.; c. infin., <r v=\"Matt.24.1\"></r>, al.; c. dat. loc., <r v=\"Heb.12.18\"></r>, <r v=\"Heb.12.22\"></r>; dat. pers., <r v=\"Matt.5.1\"></r>, and freq., <r v=\"John.12.21\"></r>, al.; ptcp., <g>προσελθών</g>, c. indic., <r v=\"Matt.8.2\"></r>, and freq., <r v=\"Mark.1.31\"></r>, <r v=\"Luke.7.14\"></r>, al.; <g>π. αὐτῷ</g>, c. indic., <r v=\"Matt.4.3\"></r>, <r v=\"Mark.6.35\"></r>. Metaph., <s n=\"(a)\">of approaching God: absol. (<r v=\"Lev.21.17\"></r>, <r v=\"Deut.21.5\"></r>, al.), <r v=\"Heb.10.1\"></r>, <r v=\"Heb.10.22\"></r>; <g>τ. θεῷ</g>, <r v=\"Heb.7.25\"></r> <r v=\"Heb.11.6\"></r>; <g>τ. θρόνῳ τ. χάριτος</g>, <r v=\"Heb.4.16\"></r>; <g>πρὸς Χριστόν</g>, <r v=\"1Pet.2.4\"></r>;</s> <s n=\"(b)\">in sense not found elsewhere (Field, <i>Notes</i>, 211), <b>to consent to</b>: <g>ὑγιαίνουσι λόγοις</g>, <r v=\"1Tim.6.3\"></r>.</s> </s>"},"G4394":{"l":"προφητεία","o":19,"ar":"<f>† <o>προφητεία</o>، <g>-ας, ἡ</g></f> <s>موهبة تفسير مشيئة الله وقصده (وممارستها)، <b>نبوة</b>، <b>تنبّؤ</b>: عن نبوة العهد القديم، <r v=\"Matt.13.14\"></r>، <r v=\"2Pet.1.20\"></r>، <r v=\"2Pet.1.21\"></r>؛ عن النبوة في العهد الجديد، <r v=\"Rom.12.6\"></r>، <r v=\"1Cor.12.10\"></r> <r v=\"1Cor.13.2\"></r> <r v=\"1Cor.14.6\"></r>، <r v=\"1Cor.14.22\"></r>، <r v=\"1Tim.4.14\"></r>، <r v=\"Rev.11.6\"></r> <r v=\"Rev.22.19\"></r>؛ جمع، <r v=\"1Cor.13.8\"></r>، <r v=\"1Thess.5.20\"></r>، <r v=\"1Tim.1.18\"></r>؛ <g>οἱ λόγοι τῆς π.</g>، <r v=\"Rev.1.3\"></r> <r v=\"Rev.22.7\"></r>، <r v=\"Rev.22.10\"></r>، <r v=\"Rev.22.18\"></r>؛ <g>τ. πνεῦμα τῆς π.</g>، <r v=\"Rev.19.10\"></r>.†</s>","en":"<f>† <o>προφητεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προψητεύω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5016\">נְבוּאָה</h>, <h n=\"H2377\">חָזוֹן</h>;]</e> </et> <s>the gift (and its exercise) of interpreting the Divine will and purpose, <b>prophecy</b>, <b>prophesying</b>: of OT prophecy, <r v=\"Matt.13.14\"></r>, <r v=\"2Pet.1.20\"></r>, <r v=\"2Pet.1.21\"></r>; of NT prophecy, <r v=\"Rom.12.6\"></r>, <r v=\"1Cor.12.10\"></r> <r v=\"1Cor.13.2\"></r> <r v=\"1Cor.14.6\"></r>, <r v=\"1Cor.14.22\"></r>, <r v=\"1Tim.4.14\"></r>, <r v=\"Rev.11.6\"></r> <r v=\"Rev.22.19\"></r>; pl., <r v=\"1Cor.13.8\"></r>, <r v=\"1Thess.5.20\"></r>, <r v=\"1Tim.1.18\"></r>; <g>οἱ λόγοι τῆς π.</g>, <r v=\"Rev.1.3\"></r> <r v=\"Rev.22.7\"></r>, <r v=\"Rev.22.10\"></r>, <r v=\"Rev.22.18\"></r>; <g>τ. πνεῦμα τῆς π.</g>, <r v=\"Rev.19.10\"></r> (Luc., FlJ, LXX, <g>π.</g>; v. Deiss., <i>BS</i>, 235 f.; MM, xxii).†</s>"},"G4357":{"l":"προσμένω","o":7,"ar":"<f><o>προσ-μένω</o>،</f> <s n=\"1.\"><b>انتظر مدة أطول</b>، <b>استمر</b>، <b>بقي</b>: <r v=\"Acts.18.18\"></r>؛ يليه <g>ἐν</g>، <r v=\"1Tim.1.3\"></r>.</s> <s n=\"2.\">مع القابل: <b>مكث مع</b>: <r v=\"Matt.15.32\"></r>، <r v=\"Mark.8.32\"></r>. ومجازيًا: <b>ظل متمسكًا بـ</b>، <b>لصق بـ</b>، <b>ثبت في</b>: <g>τ. κυρίῳ</g>، <r v=\"Acts.11.23\"></r>؛ <g>τ. χάριτι τ. θεοῦ</g>، <r v=\"Acts.13.43\"></r>؛ <g>τ. δεήσεσιν</g>، <r v=\"1Tim.5.5\"></r>.†</s>","en":"<f><o>προσ-μένω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.3.25\"></r> A (<h n=\"H2342\">חוּל</h> hi.), <r v=\"Tob.2.2\"></r> <h>א</h>, <r v=\"Wis.3.9\"></r>, <r v=\"3Macc.7.17\"></r>*;]</e> </et> <s n=\"1.\"><b>to wait longer</b>, <b>continue</b>, <b>remain still</b>: <r v=\"Acts.18.18\"></r>; seq. <g>ἐν</g>, <r v=\"1Tim.1.3\"></r>.</s> <s n=\"2.\">C. dat., <b>to remain with</b>: <r v=\"Matt.15.32\"></r>, <r v=\"Mark.8.32\"></r>. Metaph., <b>to remain attached to</b>, <b>cleave unto</b>, <b>abide in</b>: <g>τ. κυρίῳ</g>, <r v=\"Acts.11.23\"></r> (R, txt.; <g>ἐν τ. κ.</g>, R, mg., v. supr.); <g>τ. χάριτι τ. θεοῦ</g>, <r v=\"Acts.13.43\"></r>; <g>τ. δεήσεσιν</g>, <r v=\"1Tim.5.5\"></r>.†</s>"},"G4332":{"l":"προσεδρεύω","o":1,"ar":"<f>** <o>προσεδρεύω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>جلس قرب</b>.</s> <s n=\"2.\"><b>لازم، واظب على الخدمة</b>: مع القابل، <r v=\"1Cor.9.13\"></r> (انظر تحت مدخل <g>παρεδρεύω</g>).†</s>","en":"<f>** <o>προσεδρεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>πρόσεδρος</g>, <i>sitting near</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.11.40\"></r>*;]</e> </et> <s n=\"1.\"><b>to sit near</b>.</s> <s n=\"2.\"><b>to attend regularly</b>: c. dat., <r v=\"1Cor.9.13\"></r>, Rec. (v.s. <g>παρεδρεύω</g>).†</s>"},"G4310":{"l":"προπάσχω","o":1,"ar":"<f>* <o>προ-πάσχω</o>،</f> <s><b>تألّم قبلاً</b>: <r v=\"1Thess.2.2\"></r>.†</s>","en":"<f>* <o>προ-πάσχω</o>,</f> <s><b>to suffer before</b>: <r v=\"1Thess.2.2\"></r>.†</s>"},"G4383":{"l":"πρόσωπον","o":76,"ar":"<f><o>πρόσωπον</o>، <g>-ου, τό</g></f> <s n=\"1.\">بالمعنى الأصلي، عن الأشخاص؛ <s n=\"(a)\"><b>الوجه</b>، <b>المُحيّا</b>: <r v=\"Matt.6.16\"></r>، <r v=\"Matt.6.17\"></r>، <r v=\"Mark.14.65\"></r>، <r v=\"Luke.9.29\"></r>، <r v=\"2Cor.3.7\"></r>، <r v=\"Rev.4.7\"></r>، وفي مواضع أخرى؛ <g>τὸ π. τῆς γενέσεως</g> (أي <i>الوجه الطبيعي</i>)، <r v=\"Jas.1.23\"></r>؛ <g>πίπτειν ἐπὶ</g> (<g>τὰ</g>) <g>π.</g> (السقوط على الوجه)، <r v=\"Matt.17.6\"></r>، <r v=\"Luke.5.12\"></r>، <r v=\"Rev.7.11\"></r>، وفي مواضع أخرى؛ <g>ἀγνοούμενος τῷ π.</g>، <r v=\"Gal.1.22\"></r>؛ <g>π., οὐ καρδίᾳ</g>، <r v=\"1Thess.2.17\"></r>؛ <g>κατὰ πρόσωπον</g> (<i>في المقدمة</i>، <i>مواجهةً</i>)، <b>حاضرًا</b>، <b>وجهًا لوجه</b>، <r v=\"Acts.25.16\"></r>، <r v=\"2Cor.10.1\"></r>، <r v=\"2Cor.10.7\"></r>، <r v=\"Gal.2.11\"></r>؛ ونفسه مع المضاف إليه، كحرف جر مركب، <b>أمام</b>، <b>في حضرة</b>، <r v=\"Luke.2.31\"></r>، <r v=\"Acts.3.13\"></r>؛ وبالمثل <g>ἀπὸ π.</g> (العبرية <h n=\"H6440\">מִלִּפְּנֵי</h>)، <b>من وجه</b>، <b>من حضرة</b>، <r v=\"Acts.3.19\"></r>، <r v=\"Acts.5.41\"></r>، <r v=\"Acts.7.45\"></r>، <r v=\"2Thess.1.9\"></r>، <r v=\"Rev.12.14\"></r>، <r v=\"Rev.20.11\"></r>؛ <g>πρὸ π.</g> (العبرية <h n=\"H6440\">לִפְנֵי</h>)، <b>قُدّام</b>، <r v=\"Matt.11.10\"></r>، <r v=\"Mark.1.2\"></r>، <r v=\"Luke.7.27\"></r> <i>(السبعينية)</i>، وفي مواضع أخرى؛ وفي تعبيرات أخرى تشبه الأسلوب العبري: <g>βλέπειν</g> (<g>ὁρᾶν</g>، <g>θεωρεῖν</g>، <g>ἰδεῖν</g>) <g>τὸ π.</g>، <b>رأى وجه أحد</b>، أي رآه شخصيًا، <r v=\"Matt.18.10\"></r>، <r v=\"Acts.20.25\"></r>، <r v=\"Acts.20.38\"></r>، <r v=\"1Thess.3.10\"></r>، <r v=\"Rev.22.4\"></r>؛ <g>ἐμφανισθῆναι τῷ π. τοῦ θεοῦ</g>، <r v=\"Heb.9.24\"></r>؛ <g>ἐν π. Χριστοῦ</g>، <r v=\"2Cor.2.10\"></r>، <r v=\"2Cor.4.6\"></r>؛ <g>μετὰ τοῦ π. σου</g>، <b>مع وجهك</b> (أي بحضورك)، <r v=\"Acts.2.28\"></r> <i>(السبعينية)</i>؛ <g>εἰς π. τῶν ἐκκλησιῶν</g>، <r v=\"2Cor.8.24\"></r>؛ <g>στηρίζειν τὸ π.</g> (العبرية <h n=\"H7760\">שׂוּם</h> <h n=\"H6440\">פָּנִים</h>: <r v=\"Jer.21.10\"></r>، وفي مواضع أخرى)، مع المصدر، <b>ثبّت وجهه نحو</b>، <r v=\"Luke.9.51\"></r>؛ وبالمثل <g>τὸ π. αὐτοῦ ἦν πορευόμενον</g>، <r v=\"Luke.9.53\"></r>؛ <g>τὸ π. τοῦ κυρίου ἐπί</g>، <r v=\"1Pet.3.12\"></r> <i>(السبعينية)</i>؛</s> <s n=\"(b)\"><b>الهيئة</b>، <b>الشخص</b>: <g>καυχᾶσθαι ἐν π. καὶ μὴ ἐν καρδίᾳ</g>، <r v=\"2Cor.5.12\"></r> (قارن <r v=\"1Sam.16.7\"></r>)؛ ومجازيًا، كما في الأسلوب العبري، عن الحكم بحسب المظهر أو الحال أو الظروف الخارجية: <g>λαμβάνειν π.</g> (أي المحاباة)، <r v=\"Luke.20.21\"></r>، <r v=\"Gal.2.6\"></r>؛ <g>βλέπειν εἰς π.</g>، <r v=\"Matt.22.16\"></r>، <r v=\"Mark.12.14\"></r>؛ <g>θαυμάζειν πρόσωπα</g>، <r v=\"Jude.1.16\"></r>.</s> </s> <s n=\"2.\">عن الأشياء؛ <s n=\"(a)\"><b>الوجه</b>، <b>المنظر</b> (<r v=\"Ps.104.30\"></r>): <r v=\"Matt.16.3\"></r>، <r v=\"Luke.12.56\"></r>، <r v=\"Jas.1.11\"></r>؛</s> <s n=\"(b)\"><b>السطح</b> (<r v=\"Gen.2.6\"></r>): <r v=\"Luke.21.35\"></r>، <r v=\"Acts.17.26\"></r>.</s> </s>","en":"<f><o>πρόσωπον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πρός</g>, <g>ὤψ</g>),</e> <e t=\"septuagint\">[in LXX chiefly and very freq. for <h n=\"H6440\">פָּנִים</h>;]</e> </et> <s n=\"1.\">prop., of persons (so always in cl.); <s n=\"(a)\"><b>the face</b>, <b>countenance</b>: <r v=\"Matt.6.16\"></r>, <r v=\"Matt.6.17\"></r>, <r v=\"Mark.14.65\"></r>, <r v=\"Luke.9.29\"></r>, <r v=\"2Cor.3.7\"></r>, <r v=\"Rev.4.7\"></r>, al.; <g>τὸ π. τῆς γενέσεως</g> (EV, <i>natural face</i>), <r v=\"Jas.1.23\"></r>; <g>πίπτειν ἐπὶ</g> (<g>τὰ</g>) <g>π.</g>, <r v=\"Matt.17.6\"></r>, <r v=\"Luke.5.12\"></r>, <r v=\"Rev.7.11\"></r>, al.; <g>ἀγνοούμενος τῷ π.</g>, <r v=\"Gal.1.22\"></r>; <g>π., οὐ καρδίᾳ</g>, <r v=\"1Thess.2.17\"></r>; <g>κατὰ πρόσωπον</g> (<i>in front</i>, <i>facing</i>: Thuc., Xen., al.), <b>when present</b>, <b>face to face</b>, <r v=\"Acts.25.16\"></r>, <r v=\"2Cor.10.1\"></r>, <r v=\"2Cor.10.7\"></r>, <r v=\"Gal.2.11\"></r>; id. c. gen., as compound prep., <b>in the presence of</b> (not cl.; v. Bl., § 40, 9; M, <i>Pr.</i>, 99 f.; Thackeray, <i>Gr.</i>, 43 f.), <r v=\"Luke.2.31\"></r>, <r v=\"Acts.3.13\"></r>; similarly <g>ἀπὸ π.</g> (Heb. <h n=\"H6440\">מִלִּפְּנֵי</h>; v. Dalman, <i>Words</i>, 29), <b>from the presence of</b>, <r v=\"Acts.3.19\"></r> <r v=\"Acts.5.41\"></r> <r v=\"Acts.7.45\"></r>, <r v=\"2Thess.1.9\"></r>, <r v=\"Rev.12.14\"></r> <r v=\"Rev.20.11\"></r>; <g>πρὸ π.</g> (Heb. <h n=\"H6440\">לִפְנֵי</h>), <b>before</b>, <r v=\"Matt.11.10\"></r>, <r v=\"Mark.1.2\"></r>, <r v=\"Luke.7.27\"></r><i>(LXX)</i>, al.; in other phrases resembling Heb. idiom (Thackeray, <i>Gr.</i>, 42), <g>βλέπειν</g> (<g>ὁρᾶν</g>, <g>θεωρεῖν</g>, <g>ἰδεῖν</g>) <g>τὸ π.</g>, <b>to see one's face</b>, i.e. see him in person, <r v=\"Matt.18.10\"></r>, <r v=\"Acts.20.25\"></r>, <r v=\"Acts.20.38\"></r>, <r v=\"1Thess.3.10\"></r>, <r v=\"Rev.22.4\"></r>; <g>ἐμφανισθῆναι τῷ π. τοῦ θεοῦ</g>, <r v=\"Heb.9.24\"></r>; <g>ἐν π. Χριστοῦ</g>, <r v=\"2Cor.2.10\"></r> <r v=\"2Cor.4.6\"></r>; <g>μετὰ τοῦ π. σου</g>, <b>with thy presence</b>, <r v=\"Acts.2.28\"></r><i>(LXX)</i>; <g>εἰς π. τῶν ἐκκλησιῶν</g>, <r v=\"2Cor.8.24\"></r>; <g>στηρίζειν τὸ π.</g> (Heb. <h n=\"H7760\">שׂוּם</h> <h n=\"H6440\">פָּנִים</h>: <r v=\"Jer.21.10\"></r>, al.; v. Dalman, <i>Words</i>, 30), c. inf., <b>to set one's face towards</b>, <r v=\"Luke.9.51\"></r>; similarly, <g>τὸ π. αὐτοῦ ἦν πορευόμενον</g> (<i>op. cit.</i>, 31), <r v=\"Luke.9.53\"></r>; <g>τὸ π. τοῦ κυρίου ἐπί</g>, <r v=\"1Pet.3.12\"></r><i>(LXX)</i>;</s> <s n=\"(b)\"><b>form</b>, <b>person</b>: <g>καυχᾶσθαι ἐν π. καὶ μὴ ἐν καρδίᾳ</g>, <r v=\"2Cor.5.12\"></r> (cf. <r v=\"1Sam.16.7\"></r>); metaph., as in Heb. idiom, of judgment according to appearance, external condition or circumstances (<h n=\"H5375\">נשָׂאָ</h><i>probably misspelled נָשָׂא</i> <h n=\"H6440\">פָּנִים</h>; v. Dalman, <i>Words</i>, 30; Thackeray, <i>Gr.</i>, 43 f.): <g>λαμβάνειν π.</g>, <r v=\"Luke.20.21\"></r>, <r v=\"Gal.2.6\"></r>; <g>βλέπειν εἰς π.</g>, <r v=\"Matt.22.16\"></r>, <r v=\"Mark.12.14\"></r>; <g>θαυμάζειν πρόσωπα</g>, <r v=\"Jude.1.16\"></r>.</s> </s> <s n=\"2.\">Of things (cf. Dalman, <i>Words</i>, 30); <s n=\"(a)\"><b>face</b>, <b>appearance</b> (<r v=\"Ps.104.30\"></r>): <r v=\"Matt.16.3\"></r> (WH, R, mg., om.), <r v=\"Luke.12.56\"></r>, <r v=\"Jas.1.11\"></r>;</s> <s n=\"(b)\"><b>surface</b> (<r v=\"Gen.2.6\"></r>): <r v=\"Luke.21.35\"></r>, <r v=\"Acts.17.26\"></r>.</s> </s>"},"G4301":{"l":"προλαμβάνω","o":3,"ar":"<f>** <o>προ-λαμβάνω</o>،</f> <s n=\"1.\"><b>يأخذ مسبقًا</b>: مع المنصوب، <r v=\"1Cor.11.21\"></r> (لكن انظر أدناه).</s> <s n=\"2.\"><b>يسبق</b>، <b>يبادر</b>: مع المصدر (= <g>φθάνω</g>)، <r v=\"Mark.14.8\"></r>.</s> <s n=\"3.\"><b>يُدرِك</b>، <b>يُفاجئ</b>: المبني للمجهول، <r v=\"Gal.6.1\"></r> (وهنا، وربما أيضًا في <r v=\"1Cor.11.21\"></r>، يكاد يزول معنى السبق الزمني في السابقة).†</s>","en":"<f>** <o>προ-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.17.11\"></r> <h>א</h><i>2</i>, <r v=\"Wis.17.17\"></r> <h>א</h><i>2</i>B*;]</e> </et> <s n=\"1.\"><b>to take beforehand</b>: c. acc., <r v=\"1Cor.11.21\"></r> (but v. infr.).</s> <s n=\"2.\"><b>to be beforehand</b>, <b>anticipate</b> (in cl., c. acc., gen. or dat.): c. inf. (= cl. <g>φθάνω</g>, v. Bl., § 69, 4; Swete, in l.), <r v=\"Mark.14.8\"></r>.</s> <s n=\"3.\"><b>to overtake</b>, <b>surprise</b>: pass., <r v=\"Gal.6.1\"></r> (on the virtual disappearance of the temporal force of the preposition in this compound here and perhaps also in <r v=\"1Cor.11.21\"></r>, v. MM, xxi).†</s>"},"G4348":{"l":"πρόσκομμα","o":6,"ar":"<f>† <o>πρόσ-κομμα</o>، <g>-τος, τό</g></f> <s n=\"(a)\"><b>عثرة</b>، <b>تعثّر</b>: <g>λίθος προσκόμματος</g> (= <h n=\"H68\">אֶבֶן</h> <h n=\"H5063\">נֶגֶף</h>، <r v=\"Isa.8.14\"></r>)، مجازيًا، <r v=\"Rom.9.32\"></r>، <r v=\"Rom.9.33\"></r>، <r v=\"1Pet.2.8\"></r> <i>(السبعينية)</i>؛</s> <s n=\"(b)\">= <g>προσκοπή</g>، <b>سبب عثرة</b>، <b>معثرة</b>: مجازيًا، <r v=\"Rom.14.13\"></r>، <r v=\"Rom.14.20\"></r>، <r v=\"1Cor.8.9\"></r>.†</s>","en":"<f>† <o>πρόσ-κομμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>προσκόπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.33\"></r> <r v=\"Exod.34.12\"></r> (<h n=\"H4170\">מוֹקֵשׁ</h>), <r v=\"Isa.8.14\"></r> (<h n=\"H5063\">נֶגֶף</h>), <r v=\"Jdt.8.22\"></r>, <r v=\"Sir.17.25\"></r>, al.;]</e> </et> <s n=\"(a)\"><b>a stumble</b>, <b>stumbling</b>: <g>λίθος προσκόμματος</g> (= <h n=\"H68\">אֶבֶן</h> <h n=\"H5063\">נֶגֶף</h>, <r v=\"Isa.8.14\"></r>), fig., <r v=\"Rom.9.32\"></r>, <r v=\"Rom.9.33\"></r>, <r v=\"1Pet.2.8\"></r><i>(LXX)</i>;</s> <s n=\"(b)\">= <g>προσκοπή</g>, <b>an occasion of stumbling</b>, <b>a stumbling-block</b>: metaph., <r v=\"Rom.14.13\"></r>, <r v=\"Rom.14.20\"></r>, <r v=\"1Cor.8.9\"></r> (Plut.).†</s> <sy><i>SYN.</i>: <g>σκάνδαλον</g> (cf. Cremer, 752 f.).</sy>"},"G4356":{"l":"πρόσλημψις","o":1,"ar":"<f>* <o>πρόσ-λημψις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>افتراض</b>.</s> <s n=\"2.\"><b>قبول، اقتبال</b> (قارن <g>προσλαμβάνω</g>): <r v=\"Rom.11.15\"></r>.†</s>","en":"<f>* <o>πρόσ-λημψις</o> (Rec. <g>-ληψις</g>, as in Att.), <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσλαμβάνω</g>),</e> </et> <s n=\"1.\"><b>an assumption</b> (Plat.).</s> <s n=\"2.\"><b>a receiving</b> (cf. <g>προσλαμβάνω</g>): <r v=\"Rom.11.15\"></r>.†</s>"},"G4306":{"l":"προνοέω","o":3,"ar":"<f><o>προ-νοέω</o>، <g>-ῶ</g>، وفعل لازم الصيغة الوسطى <g>-έομαι, οῦμαι</g>،</f> <s n=\"1.\"><b>يرى مسبقًا</b>.</s> <s n=\"2.\"><b>يعتني بـ، يدبّر</b> (<i>يهتم بـ</i>): مع المنصوب للشيء، <g>καλά</g>، <r v=\"Rom.12.17\"></r> (<g>-ούμενοι</g>)، <r v=\"2Cor.8.21\"></r> (<g>-οῦμεν</g>).</s> <s n=\"3.\"><b>يعول، يعتني بـ</b> (يليه <g>περί</g>، <r v=\"Wis.6.7\"></r>): مع المضاف إليه للشخص، <r v=\"1Tim.5.8\"></r>.†</s>","en":"<f><o>προ-νοέω</o>, <g>-ῶ</g>, and depon. <g>-έομαι, οῦμαι</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.11.37\"></r> (<h n=\"H995\">בִּין</h>), <r v=\"Wis.6.7\"></r>, al.;]</e> </et> <s n=\"1.\"><b>to foresee</b>.</s> <s n=\"2.\"><b>to provide</b> (RV,<i> take thought for</i>): c. acc. rei, <g>καλά</g>, <r v=\"Rom.12.17\"></r> (<g>-ούμενοι</g>), <r v=\"2Cor.8.21\"></r> (<g>-οῦμεν</g>).</s> <s n=\"3.\"><b>to provide for</b> (seq. <g>περί</g>, <r v=\"Wis.6.7\"></r>): c. gen. pers., <r v=\"1Tim.5.8\"></r> (<g>-εῖ</g>, WH, mg., <g>-εῖται</g>).†</s>"},"G4341":{"l":"προσκαλέω","o":29,"ar":"<f><o>προσ-καλέω</o>، <g>-ῶ</g>،</f> <s><b>نادى</b>. الصيغة الوسطى: <b>دعا إليه</b>: مع منصوب الشخص، <r v=\"Matt.10.1\"></r>، <r v=\"Mark.3.13\"></r> <r v=\"Mark.6.7\"></r>، <r v=\"Luke.7.19\"></r>، <r v=\"Acts.5.40\"></r>، <r v=\"Jas.5.14\"></r>، وفي مواضع أخرى. مجازيًا، عن الدعوة الإلهية: <r v=\"Acts.2.39\"></r>؛ مع المصدر، <r v=\"Acts.16.10\"></r>؛ يليه <g>εἰς</g>، <r v=\"Acts.13.2\"></r>.†</s>","en":"<f><o>προσ-καλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7121\">קרא</h>;]</e> </et> <s><b>to call to</b>. Mid., <b>to call to oneself</b> (v. M, <i>Pr.</i>, 157): c. acc. pers., <r v=\"Matt.10.1\"></r>, <r v=\"Mark.3.13\"></r> <r v=\"Mark.6.7\"></r>, <r v=\"Luke.7.19\"></r>, <r v=\"Acts.5.40\"></r>, <r v=\"Jas.5.14\"></r>, al. Metaph., of the Divine call: <r v=\"Acts.2.39\"></r>; c. inf., <r v=\"Acts.16.10\"></r> (v. Bl., § 69, 4); seq. <g>εἰς</g>, <r v=\"Acts.13.2\"></r>.†</s>"},"G4378":{"l":"πρόσχυσις","o":1,"ar":"<f>*† <o>πρόσ-χυσις</o>، <g>-εως, ἡ</g>،</f> <s><b>رشّ</b> أو <b>سكب على</b>: <r v=\"Heb.11.28\"></r>.†</s>","en":"<f>*† <o>πρόσ-χυσις</o>, <g>-εως, ἡ</g>,</f> <s><b>a pouring</b> or <b>sprinkling upon</b>: <r v=\"Heb.11.28\"></r>.†</s>"},"G4398":{"l":"προφῆτις","o":2,"ar":"<f><o>προφῆτις</o>، <g>-ιδος, ἡ</g> مؤنث <g>προφήτης</g>،</f> <s><b>نبيّة</b>: <r v=\"Luke.2.36\"></r>، <r v=\"Rev.2.20\"></r>.†</s>","en":"<f><o>προφῆτις</o>, <g>-ιδος, ἡ</g> fem, of <g>προφήτης</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.15.20\"></r>, <r v=\"Judg.4.4\"></r>, <r v=\"2Kgs.22.14\"></r>, <r v=\"2Chr.34.22\"></r>, <r v=\"Isa.8.3\"></r> (<h n=\"H5031\">נְבִיאָה</h>)*;]</e> </et> <s><b>a prophetess</b>: <r v=\"Luke.2.36\"></r>, <r v=\"Rev.2.20\"></r>.†</s>"},"G4380":{"l":"προσωπολημπτέω","o":1,"ar":"<f>*† <o>προσωπολημπτέω</o>، <g>-ῶ</g></f> <s><b>حابى الوجوه، حابى</b>: <r v=\"Jas.2.9\"></r>.†</s>","en":"<f>*† <o>προσωπολημπτέω</o> (Rec. <g>-ληπτ-</g>), <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>-λήμπτης</g>, q.v.),</e> </et> <s><b>to have respect of persons</b>: <r v=\"Jas.2.9\"></r>.†</s>"},"G4317":{"l":"προσάγω","o":4,"ar":"<f><o>προσ-άγω</o>،</f> <s n=\"1.\">متعدٍّ: <b>قدّم</b> أو <b>قاد</b>: مع المنصوب والقابل، <r v=\"Acts.16.20\"></r>؛ مجازيًا، <g>τ. θεῷ</g>، <r v=\"1Pet.3.18\"></r>؛ يليه <g>ὧδε</g>، <r v=\"Luke.9.41\"></r>؛ المبني للمجهول، مع القابل، <r v=\"Matt.18.24\"></r>؛ وبالمعنى القضائي: <b>استدعى</b> (للمحاكمة): <r v=\"Acts.12.6\"></r>.</s> <s n=\"2.\">لازم: <b>اقترب</b>، <b>دنا</b> (<r v=\"Josh.3.9\"></r>، <r v=\"Jer.46.3\"></r>، وفي مواضع أخرى): مع القابل، <r v=\"Acts.27.27\"></r>.†</s>","en":"<f><o>προσ-άγω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7126\">קרב</h> hi., also for <h n=\"H5066\">נגשׁ</h> etc.;]</e> </et> <s n=\"1.\">trans., <b>to bring</b> or <b>lead</b>: c. acc. et dat., <r v=\"Acts.16.20\"></r>; metaph., <g>τ. θεῷ</g>, <r v=\"1Pet.3.18\"></r>; seq. <g>ὧδε</g>, <r v=\"Luke.9.41\"></r>; pass., c. dat., <r v=\"Matt.18.24\"></r> (<g>προσηνέχθη</g>, T); in forensic sense, <b>to summon</b>: <r v=\"Acts.12.6\"></r> (<g>προαγαγεῖν</g>, T, WH, mg., R).</s> <s n=\"2.\">Intrans., <b>to draw near</b>, <b>approach</b> (<r v=\"Josh.3.9\"></r>, <r v=\"Jer.46.3\"></r>, al.): c. dat., <r v=\"Acts.27.27\"></r> (WH, <g>προσαχεῖν</g>).†</s>"},"G4328":{"l":"προσδοκάω","o":16,"ar":"<f><o>προσ-δοκάω</o>، <g>-ῶ</g></f> <s><b>انتظر</b>، <b>توقّع</b>: <r v=\"Matt.24.50\"></r>، <r v=\"Luke.3.15\"></r> <r v=\"Luke.12.46\"></r>، <r v=\"Acts.27.33\"></r> <r v=\"Acts.28.6\"></r>؛ مع منصوب الشخص، <r v=\"Matt.11.3\"></r>، <r v=\"Luke.1.21\"></r> <r v=\"Luke.7.19\"></r>، <r v=\"Luke.7.20\"></r> <r v=\"Luke.8.40\"></r>، <r v=\"Acts.10.24\"></r>؛ مع منصوب الشيء، <r v=\"2Pet.3.12-2Pet.3.14\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.28.6\"></r>؛ مع المصدر، <r v=\"Acts.3.5\"></r>.†</s>","en":"<f><o>προσ-δοκάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(the simple verb exists only in the forms <g>δοκέω</g>, <g>-εύω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.104.27\"></r> (<h n=\"H7663\">שׂבר</h> pi.), etc.;]</e> </et> <s><b>to await</b>, <b>expect</b>: <r v=\"Matt.24.50\"></r>, <r v=\"Luke.3.15\"></r> <r v=\"Luke.12.46\"></r>, <r v=\"Acts.27.33\"></r> <r v=\"Acts.28.6\"></r>; c. acc. pers., <r v=\"Matt.11.3\"></r>, <r v=\"Luke.1.21\"></r> <r v=\"Luke.7.19\"></r>, <r v=\"Luke.7.20\"></r> <r v=\"Luke.8.40\"></r>, <r v=\"Acts.10.24\"></r>; c. acc. rei, <r v=\"2Pet.3.12-2Pet.3.14\"></r>; c. acc. et inf., <r v=\"Acts.28.6\"></r>; c. inf., <r v=\"Acts.3.5\"></r>.†</s>"},"G4360":{"l":"προσοχθίζω","o":2,"ar":"<f>† <o>προσ-οχθίζω</o>،</f> <s><b>غضب على</b>، <b>مقت</b>: مع القابل، <r v=\"Heb.3.10\"></r><i>(السبعينية)</i>، <r v=\"Heb.3.17\"></r>.†</s>","en":"<f>† <o>προσ-οχθίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.26.15\"></r>, al. (<h n=\"H1602\">גּעל</h>); <r v=\"Lev.18.25\"></r>, al. (<h n=\"H6958\">קוֹא</h>), <r v=\"Ps.95.10\"></r>, <r v=\"Ezek.36.31\"></r> (<h n=\"H6962\">קוּט</h>), <r v=\"Sir.6.25\"></r>, al. (other writers use <g>ὀχθέω</g>, rarely <g>-ίζω</g>);]</e> </et> <s><b>to be angry with</b>: c. dat., <r v=\"Heb.3.10\"></r><i>(LXX)</i>, <r v=\"Heb.3.17\"></r>.†</s>"},"G4316":{"l":"προσαγορεύω","o":1,"ar":"<f><o>προσ-αγορεύω</o>،</f> <s><b>خاطب</b>، <b>حيّا</b>، <b>سلّم على</b>؛ ومن ثَمّ <b>دعا باسم</b>، <b>لقّب</b>، <b>سمّى</b>: مع منصوبين، المبني للمجهول، <r v=\"Heb.5.10\"></r>.†</s>","en":"<f><o>προσ-αγορεύω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.23.6\"></r> (<r v=\"Deut.23.7\"></r>) (<h n=\"H1875\">דָּרַשׁ</h>), <r v=\"2Esd.10.11\"></r>, <r v=\"2Esd.B.1\"></r> (<h n=\"H3034\">ידה</h> hith.), <r v=\"Wis.14.22\"></r>, <r v=\"1Macc.14.40\"></r>, <r v=\"2Macc.1.36\"></r> <r v=\"2Macc.4.7\"></r> <r v=\"2Macc.10.9\"></r> <r v=\"2Macc.14.37\"></r>*;]</e> </et> <s><b>to address</b>, <b>greet</b>, <b>salute</b>; hence, <b>to call by name</b>, <b>address</b>, <b>style</b>: c. dupl. acc., pass., <r v=\"Heb.5.10\"></r>.†</s>"},"G4374":{"l":"προσφέρω","o":47,"ar":"<f><o>προσ-φέρω</o>،</f> <s n=\"1.\"><b>يُحضِر إلى</b>، <b>يقود إلى</b>: مع المنصوب والقابل للشخص، <r v=\"Matt.4.24\"></r> <r v=\"Matt.8.16\"></r> <r v=\"Matt.9.2\"></r>، <r v=\"Matt.9.32\"></r> <r v=\"Matt.14.35\"></r> <r v=\"Matt.17.16\"></r>، <r v=\"Mark.2.4\"></r> (بتقدير <g>αὐτόν</g>) <r v=\"Mark.10.13\"></r>، <r v=\"Luke.18.15\"></r> <r v=\"Luke.23.14\"></r>؛ المبني للمجهول، <r v=\"Matt.12.22\"></r> <r v=\"Matt.18.24\"></r> <r v=\"Matt.19.13\"></r>؛ مع المنصوب للشيء، <r v=\"Matt.25.20\"></r>؛ ونفسه مع القابل للشخص، <r v=\"Matt.22.19\"></r>، <r v=\"Luke.23.36\"></r>؛ <g>τ. στόματι</g>، <r v=\"John.19.29\"></r>؛ مجازيًا، مع القابل للشخص: <b>يعامل</b>، <r v=\"Heb.12.7\"></r>.</s> <s n=\"2.\"><b>يقدِّم</b>: <r v=\"Matt.2.11\"></r>، <r v=\"Acts.8.18\"></r>؛ خاصةً (كما يكثر في السبعينية) الذبائح والقرابين والصلوات لله: مطلقًا، يليه <g>περί</g> (<g>ὑπέρ</g>)، <r v=\"Mark.1.44\"></r>، <r v=\"Luke.5.14\"></r>، <r v=\"Heb.5.1\"></r>، <r v=\"Heb.5.3\"></r> <r v=\"Heb.9.7\"></r> <r v=\"Heb.10.12\"></r>؛ المبني للمجهول، <r v=\"Acts.21.26\"></r>؛ مع المنصوب للشيء (<g>δῶρον</g>، <g>θυσίαν</g>، <g>λυτρείαν</g>، <g>προσφοράν</g>)، <r v=\"Matt.5.23\"></r>، <r v=\"Matt.5.24\"></r> (مضارع بمعنى الماضي البسيط) <r v=\"Matt.8.4\"></r>، <r v=\"John.16.2\"></r>، <r v=\"Acts.7.42\"></r> <r v=\"Acts.21.26\"></r>، <r v=\"Heb.5.1\"></r> <r v=\"Heb.8.3\"></r>، <r v=\"Heb.8.4\"></r> <r v=\"Heb.9.7\"></r>، <r v=\"Heb.9.9\"></r> <r v=\"Heb.10.1\"></r>، <r v=\"Heb.10.2\"></r>، <r v=\"Heb.10.8\"></r>، <r v=\"Heb.10.11\"></r>، <r v=\"Heb.10.12\"></r>؛ <g>δεήσεις τε κ. ἱκετηρίας</g>، <r v=\"Heb.5.7\"></r>؛ مع المنصوب للشخص، <r v=\"Heb.11.17\"></r> (ماضٍ ناقص بمعنى الشروع والمحاولة)؛ عن المسيح، <r v=\"Heb.7.27\"></r> <r v=\"Heb.9.14\"></r>، <r v=\"Heb.9.25\"></r>، <r v=\"Heb.9.28\"></r>.†</s>","en":"<f><o>προσ-φέρω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7126\">קרב</h> hi.;]</e> </et> <s n=\"1.\"><b>to bring to</b>, <b>lead to</b>: c. acc. et dat. pers., <r v=\"Matt.4.24\"></r> <r v=\"Matt.8.16\"></r> <r v=\"Matt.9.2\"></r>, <r v=\"Matt.9.32\"></r> <r v=\"Matt.14.35\"></r> <r v=\"Matt.17.16\"></r>, <r v=\"Mark.2.4\"></r> (WH, R, txt.; sc. <g>αὐτόν</g>) <r v=\"Mark.10.13\"></r>, <r v=\"Luke.18.15\"></r> <r v=\"Luke.23.14\"></r>; pass., <r v=\"Matt.12.22\"></r> (act., WH, txt.) <r v=\"Matt.18.24\"></r> (<g>προσήχθη</g>, WH) <r v=\"Matt.19.13\"></r>; c. acc. rei, <r v=\"Matt.25.20\"></r>; id. c. dat. pers., <r v=\"Matt.22.19\"></r>, <r v=\"Luke.23.36\"></r>; <g>τ. στόματι</g>, <r v=\"John.19.29\"></r>; metaph., c. dat pers., <b>to deal with</b>, <r v=\"Heb.12.7\"></r> (cl.).</s> <s n=\"2.\"><b>to offer</b>: <r v=\"Matt.2.11\"></r>, <r v=\"Acts.8.18\"></r>; esp. (as freq. in LXX; cf. FlJ, <i>Ant.</i>, iii, 9, 3) sacrifices, gifts and prayers to God: absol., seq. <g>περί</g> (<g>ὑπέρ</g>), <r v=\"Mark.1.44\"></r>, <r v=\"Luke.5.14\"></r>, <r v=\"Heb.5.1\"></r>, <r v=\"Heb.5.3\"></r> <r v=\"Heb.9.7\"></r> <r v=\"Heb.10.12\"></r>; pass., <r v=\"Acts.21.26\"></r>; c. acc. rei (<g>δῶρον</g>, <g>θυσίαν</g>, <g>λυτρείαν</g>, <g>προσφοράν</g>), <r v=\"Matt.5.23\"></r>, <r v=\"Matt.5.24\"></r> (aoristic pres.; M, <i>Pr.</i>, 247) <r v=\"Matt.8.4\"></r>, <r v=\"John.16.2\"></r>, <r v=\"Acts.7.42\"></r> <r v=\"Acts.21.26\"></r>, <r v=\"Heb.5.1\"></r> <r v=\"Heb.8.3\"></r>, <r v=\"Heb.8.4\"></r> <r v=\"Heb.9.7\"></r>, <r v=\"Heb.9.9\"></r> <r v=\"Heb.10.1\"></r>, <r v=\"Heb.10.2\"></r>, <r v=\"Heb.10.8\"></r>, <r v=\"Heb.10.11\"></r>, <r v=\"Heb.10.12\"></r>; <g>δεήσεις τε κ. ἱκετηρίας</g>, <r v=\"Heb.5.7\"></r>; c. acc. pers., <r v=\"Heb.11.17\"></r> (conative impf.; M, <i>Pr.</i>, 129); of Christ, <r v=\"Heb.7.27\"></r> (<g>ἀνενέγκας</g>, WH, txt.) <r v=\"Heb.9.14\"></r>, <r v=\"Heb.9.25\"></r>, <r v=\"Heb.9.28\"></r>.†</s>"},"G4372":{"l":"πρόσφατος","o":1,"ar":"<f><o>πρόσφατος</o>، <g>-ον</g></f> <s n=\"1.\">أصلاً: <b>مذبوح حديثًا</b>.</s> <s n=\"2.\">وعمومًا: <b>جديد</b>، <b>حديث</b>، <b>طريّ</b>: <g>ὁδός</g>، <r v=\"Heb.10.20\"></r>.†</s>","en":"<f><o>πρόσφατος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(on the derivation, v. Boisacq, s.v. and cf. <g>-ως</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.6.3\"></r> (<h n=\"H3892\">לַח</h>), <r v=\"Deut.32.17\"></r>, <r v=\"Eccl.1.9\"></r> (<h n=\"H2319\">חָדָשׁ</h>), <r v=\"Ps.81.9\"></r> (<h n=\"H2114\">זוּר</h>), <r v=\"Sir.9.10\"></r>*;]</e> </et> <s n=\"1.\">originally, <b>freshly slain</b>.</s> <s n=\"2.\">Generally (from Æsch. on), <b>new</b>, <b>fresh</b>, <b>recent</b>: <g>ὁδός</g>, <r v=\"Heb.10.20\"></r> (v. MM, <i>Exp.</i>, xxi; Rutherford, <i>NPhr.</i>, 471 f.).†</s>"},"G4303":{"l":"προμαρτύρομαι","o":1,"ar":"<f>*† <o>προ-μαρτύρομαι</o>،</f> <s><b>يشهد مسبقًا</b> (قارن <g>μαρτύρομαι</g>): <r v=\"1Pet.1.11\"></r>.†</s>","en":"<f>*† <o>προ-μαρτύρομαι</o>,</f> <s><b>to protest beforehand</b> (cf. <g>μαρτύρομαι</g>, and V. Hort, in l.): <r v=\"1Pet.1.11\"></r> (elsewhere only in Theod. Met., xiv/AD.).†</s>"},"G4381":{"l":"προσωπολήμπτης","o":1,"ar":"<f>*† <o>προσωπο-λήμπτης</o>، <g>-ου, ὁ</g> </f> <s><b>مُحابٍ للوجوه</b>: <r v=\"Acts.10.34\"></r>.†</s>","en":"<f>*† <o>προσωπο-λήμπτης</o> (Rec. <g>-λήπτης</g>, v. Bl., § 6, 8), <g>-ου, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>πρόσωπον λαμβάνειν</g>, v.s. <g>πρόσωπον</g>),</e> </et> <s><b>a respecter of persons</b>: <r v=\"Acts.10.34\"></r> (on this group of cognate forms, v. Mayor, <i>ja.</i>, 78 f.; and cf. Thackeray, <i>Gr.</i>, 44).†</s>"},"G4385":{"l":"προτείνω","o":1,"ar":"<f>** <o>προ-τείνω</o>، [في السبعينية: <r v=\"3Macc.2.1\"></r>؛]</f> <s><b>مدَّ</b>، <b>بسط</b>: عن التهيئة للجلد، <r v=\"Acts.22.25\"></r>.†</s>","en":"<f>** <o>προ-τείνω</o>, [in LXX: II Mac<i>7</i>, <r v=\"3Macc.2.1\"></r>*;]</f> <s><b>to stretch out</b>, <b>stretch forth</b>: of preparations for scourging (v. Field, <i>Notes</i>, 136 f.), <r v=\"Acts.22.25\"></r>.†</s>"},"G4365":{"l":"προσπορεύομαι","o":1,"ar":"<f><o>προσ-πορεύομαι</o>،</f> <s><b>تقدَّم إلى</b>، <b>اقترب</b>: مع قابل الشخص، <r v=\"Mark.10.35\"></r>.†</s>","en":"<f><o>προσ-πορεύομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7126\">קרב</h>, <h n=\"H5066\">נגשׁ</h>, etc.;]</e> </et> <s><b>to come near</b>, <b>approach</b>: c. dat. pers., <r v=\"Mark.10.35\"></r>.†</s>"},"G4367":{"l":"προστάσσω","o":7,"ar":"<f><o>προσ-τάσσω</o>،</f> <s n=\"1.\">مع منصوب الشخص: <b>وضع عند</b>، <b>ألحق بـ</b>.</s> <s n=\"2.\"><b>أمر</b>، <b>أوصى</b>، <b>عيّن</b>: <r v=\"Luke.5.14\"></r>؛ مع قابل الشخص، <r v=\"Matt.1.24\"></r>؛ مع منصوب الشيء، <r v=\"Matt.8.4\"></r>، <r v=\"Mark.1.44\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.10.48\"></r>؛ المبني للمجهول، <r v=\"Acts.10.33\"></r> <r v=\"Acts.17.26\"></r>.†</s>","en":"<f><o>προσ-τάσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6680\">צוה</h> pi.;]</e> </et> <s n=\"1.\">c. acc. pers., <b>to place at</b>, <b>to attach to</b>.</s> <s n=\"2.\"><b>to give a command</b>, <b>enjoin</b>, <b>appoint</b>: <r v=\"Luke.5.14\"></r>; c. dat. pers., <r v=\"Matt.1.24\"></r>; c. acc. rei, <r v=\"Matt.8.4\"></r>, <r v=\"Mark.1.44\"></r>; c. acc. et inf., <r v=\"Acts.10.48\"></r>; pass., <r v=\"Acts.10.33\"></r> <r v=\"Acts.17.26\"></r>.†</s>"},"G4384":{"l":"προτάσσω","o":1,"ar":"<f>** <o>προ-τάσσω</o>،</f> <s n=\"1.\"><b>وضع في المقدّمة</b>.</s> <s n=\"2.\"><b>رتّب مسبقًا، عيّن سابقًا</b>: <r v=\"Acts.17.26\"></r>، في النص المستلَم (بدل <g>προστ.</g> في سائر الطبعات).†</s>","en":"<f>** <o>προ-τάσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.36\"></r> R (<g>Α</g>, <g>προστ-</g>)*;]</e> </et> <s n=\"1.\"><b>to place in front</b>.</s> <s n=\"2.\"><b>to arrange beforehand</b>: <r v=\"Acts.17.26\"></r>, Rec. (for <g>προστ.</g>, Edd.).†</s>"},"G4313":{"l":"προπορεύω","o":2,"ar":"<f><o>προ-πορεύω</o>،</f> <s><b>جعله يتقدّم</b>. المبني للمجهول والصيغة الوسطى: <b>تقدّم أمام</b>: <r v=\"Luke.1.76\"></r>، <r v=\"Acts.7.40\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>προ-πορεύω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1980\">הלךְ</h>, also for <h n=\"H5674\">עבר</h>, etc.;]</e> </et> <s><b>to make to go before</b>. Pass. and mid., <b>to go before</b>: <r v=\"Luke.1.76\"></r>, <r v=\"Acts.7.40\"></r><i>(LXX)</i>.†</s>"},"G4320":{"l":"προσαναβαίνω","o":1,"ar":"<f><o>προσ-ανα-βαίνω</o>،</f> <s n=\"1.\"><b>صعد معهم أيضًا</b>.</s> <s n=\"2.\"><b>ارتفع إلى فوق</b>: <r v=\"Luke.14.10\"></r>.†</s>","en":"<f><o>προσ-ανα-βαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.19.23\"></r>, al. (<h n=\"H5927\">עלה</h>);]</e> </et> <s n=\"1.\"><b>to go up besides</b>.</s> <s n=\"2.\"><b>to go up higher</b>: <r v=\"Luke.14.10\"></r>.†</s>"},"G4326":{"l":"προσδέομαι","o":1,"ar":"<f><o>προσ-δέομαι</o>،</f> <s><b>احتاج إلى المزيد</b>، <b>احتاج فوق ذلك</b>: <r v=\"Acts.17.25\"></r>.†</s>","en":"<f><o>προσ-δέομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.12.9\"></r> <h n=\"H2637\">חָסֵר</h>, Si<i>6</i>*;]</e> </et> <s><b>to want further</b>, <b>need in addition</b>: <r v=\"Acts.17.25\"></r>.†</s>"},"G4324":{"l":"προσαπειλέω","o":1,"ar":"<f>** <o>προσ-απειλέω</o>، <g>-ῶ</g>،</f> <s><b>زاد تهديدًا، هدّد أيضًا</b>: <r v=\"Acts.4.21\"></r>.†</s>","en":"<f>** <o>προσ-απειλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.13.3\"></r> <h>א</h>*;]</e> </et> <s><b>to threaten further</b>: <r v=\"Acts.4.21\"></r>.†</s>"},"G4319":{"l":"προσαιτέω","o":1,"ar":"<f><o>προσ-αιτέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>يسأل أيضًا</b>.</s> <s n=\"2.\"><b>يواصل السؤال</b>؛ ومن ثمّ <b>يُلحّ</b>، <b>يستعطي</b>، <b>يطلب صدقة</b>: <r v=\"John.9.8\"></r>.†</s>","en":"<f><o>προσ-αιτέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.27.14\"></r>*;]</e> </et> <s n=\"1.\"><b>to ask besides</b>.</s> <s n=\"2.\"><b>to continue asking</b>; hence, <b>to importune</b>, <b>beg</b>, <b>ask alms</b>: <r v=\"John.9.8\"></r>.†</s>"},"G4331":{"l":"προσεγγίζω","o":1,"ar":"<f>† <o>προσ-εγγίζω</o>،</f> <s n=\"1.\">عند الكتّاب المتأخرين: متعدٍّ، <b>يُقرِّب</b>.</s> <s n=\"2.\">لازم، <b>يقترب</b>: مع القابل، <r v=\"Mark.2.4\"></r>.†</s>","en":"<f>† <o>προσ-εγγίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5066\">נגשׁ</h>, <h n=\"H7126\">קרב</h>;]</e> </et> <s n=\"1.\">trans., <b>to bring near</b> (Luc.).</s> <s n=\"2.\">Intrans., <b>to approach</b>: c. dat., <r v=\"Mark.2.4\"></r> (WH, <g>προσενέγκαι</g>).†</s>"},"G4354":{"l":"προσλαλέω","o":2,"ar":"<f><o>προσ-λαλέω</o>، <g>-ῶ</g>،</f> <s><b>يخاطب، يكلّم</b>: <r v=\"Acts.28.20\"></r>؛ مع القابل للشخص، <r v=\"Acts.13.43\"></r>.†</s>","en":"<f><o>προσ-λαλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.4.16\"></r> AB<i>2</i> (<h n=\"H1696\">דּבר</h> pi.), <r v=\"Wis.13.17\"></r>*;]</e> </et> <s><b>to speak to</b>: <r v=\"Acts.28.20\"></r>; c. dat. pers., <r v=\"Acts.13.43\"></r>.†</s>"},"G4339":{"l":"προσήλυτος","o":4,"ar":"<f>† <o>προσήλυτος</o>، <g>-ον</g></f> <s n=\"1.\"><b>القادم</b>، <b>الغريب</b>.</s> <s n=\"2.\">عن المتهوِّدين (الداخلين في اليهودية): <b>دخيل</b>: <r v=\"Matt.23.15\"></r>، <r v=\"Acts.2.10\"></r> <r v=\"Acts.6.5\"></r> <r v=\"Acts.13.43\"></r>.†</s>","en":"<f>† <o>προσήλυτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>προσελαύνω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1616\">גֵּר</h>;]</e> </et> <s n=\"1.\"><b>one who has arrived</b>, <b>a stranger</b>.</s> <s n=\"2.\">Of converts to Judaism, <b>a proselyte</b> (v. <i>DB</i>, s.v.): <r v=\"Matt.23.15\"></r>, <r v=\"Acts.2.10\"></r> <r v=\"Acts.6.5\"></r> <r v=\"Acts.13.43\"></r>.†</s>"},"G4379":{"l":"προσψαύω","o":1,"ar":"<f>* <o>προσ-ψαύω</o>،</f> <s>في الشعر وعند الكتّاب المتأخرين: <b>لمس، مسّ</b>: مع القابل، <r v=\"Luke.11.46\"></r>.†</s>","en":"<f>* <o>προσ-ψαύω</o>,</f> <s>in poët. and late writers, <b>to touch</b>: c. dat., <r v=\"Luke.11.46\"></r>.†</s>"},"G4325":{"l":"προσδαπανάω","o":1,"ar":"<f>*† <o>προσ-δαπανάω</o>، <g>-ῶ</g>،</f> <s><b>أنفق أكثر</b>: مع المنصوب، <r v=\"Luke.10.35\"></r>.†</s>","en":"<f>*† <o>προσ-δαπανάω</o>, <g>-ῶ</g>,</f> <s><b>to spend besides</b>: c. acc., <r v=\"Luke.10.35\"></r>.†</s> <sy><i>SYN.</i>: <g>προσαναλίσκω</g>.</sy>"},"G4373":{"l":"προσφάτως","o":1,"ar":"<f><o>προσφάτως</o>،</f> ظرف <s><b>حديثًا</b>: <r v=\"Acts.18.2\"></r>.†</s>","en":"<f><o>προσφάτως</o>,</f> adv. <et> <e t=\"derivation\">(v.s. <g>πρόσφατος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.24.5\"></r> (<h n=\"H2319\">חָדָשׁ</h>), <r v=\"Jdt.4.3\"></r>, <r v=\"Jdt.4.5\"></r>, <r v=\"Ezek.11.3\"></r>, <r v=\"2Macc.14.36\"></r>*;]</e> </et> <s><b>recently</b>: <r v=\"Acts.18.2\"></r> (v. MM, <i>Exp.</i>, xxi).†</s>"},"G4333":{"l":"προσεργάζομαι","o":1,"ar":"<f>* <o>προσ-εργάζομαι</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عمل</b> أو <b>خدم زيادةً</b>.</s> <s n=\"2.\"><b>ربح زيادةً</b>، بالعمل أو التجارة: <r v=\"Luke.19.16\"></r>.†</s>","en":"<f>* <o>προσ-εργάζομαι</o>,</f> <s n=\"1.\"><b>to work</b> or <b>do service besides</b> (Hdt., Plut.).</s> <s n=\"2.\"><b>to gain besides</b>, by working or trading: <r v=\"Luke.19.16\"></r> (Xen.).†</s>"},"G4391":{"l":"προϋπάρχω","o":2,"ar":"<f>** <o>προ-ϋπ-άρχω</o>،</f> <s n=\"1.\"><b>سبق فكان في</b>.</s> <s n=\"2.\"><b>كان من قبلُ</b> أو <b>سابقًا</b>: مع اسم الفاعل، <r v=\"Luke.23.12\"></r>، <r v=\"Acts.8.9\"></r>.†</s>","en":"<f>** <o>προ-ϋπ-άρχω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.42.18\"></r>*;]</e> </et> <s n=\"1.\"><b>to be beforehand in</b>.</s> <s n=\"2.\"><b>to be before</b> or <b>previously</b>: c. ptcp., <r v=\"Luke.23.12\"></r>, <r v=\"Acts.8.9\"></r>.†</s>"},"G4351":{"l":"προσκυλίω","o":2,"ar":"<f>* <o>προσ-κυλίω</o>،</f> <s><b>دحرج</b>، <b>دحرج إلى</b>: مع المنصوب والقابل، <r v=\"Matt.27.60\"></r>؛ المنصوب يليه <g>ἐπί</g>، <r v=\"Mark.15.46\"></r>.†</s>","en":"<f>* <o>προσ-κυλίω</o>,</f> <s><b>to roll up</b>, <b>roll to</b>: c. acc. et dat., <r v=\"Matt.27.60\"></r>; acc. seq. <g>ἐπί</g>, <r v=\"Mark.15.46\"></r>.†</s>"},"G4393":{"l":"προφέρω","o":2,"ar":"<f><o>προ-φέρω</o>،</f> <s><b>أخرج</b>: مع منصوب الشيء، يليه <g>ἐκ</g>، <r v=\"Luke.6.45\"></r>.†</s>","en":"<f><o>προ-φέρω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.10.13\"></r> (<h n=\"H4672\">מצא</h> ni.), <r v=\"Tob.9.5\"></r>, al.;]</e> </et> <s><b>to bring forth</b>: c. acc. rei, seq. <g>ἐκ</g>, <r v=\"Luke.6.45\"></r>.†</s>"},"G4361":{"l":"πρόσπεινος","o":1,"ar":"<f>*† <o>πρόσπεινος</o>، <g>-ον</g></f> <s><b>جائع</b>: <r v=\"Acts.10.10\"></r>.†</s>","en":"<f>*† <o>πρόσπεινος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>πεῖωα</g>, <i>hunger</i>),</e> </et> <s><b>hungry</b>: <r v=\"Acts.10.10\"></r>.†</s>"},"G4363":{"l":"προσπίπτω","o":8,"ar":"<f><o>προσ-πίπτω</o>،</f> <s n=\"1.\"><b>وقع على</b>، <b>صدم</b>: مع القابل، عن الريح، <r v=\"Matt.7.25\"></r>.</s> <s n=\"2.\"><b>خرّ عند قدمي أحد</b>، <b>سجد أمام</b>: مطلقًا، يليه <g>πρός</g>، <r v=\"Mark.7.25\"></r>؛ مع القابل للشخص، <r v=\"Mark.3.11\"></r> <r v=\"Mark.5.33\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"Luke.8.47\"></r>، <r v=\"Acts.16.29\"></r>؛ <g>τ. γόνασιν</g>، <r v=\"Luke.5.8\"></r>.†</s>","en":"<f><o>προσ-πίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5307\">נפל</h>, <h n=\"H5060\">נגע</h> hi., <h n=\"H3766\">כּרע</h>;]</e> </et> <s n=\"1.\"><b>to fall upon</b>, <b>strike against</b>: c. dat., of wind, <r v=\"Matt.7.25\"></r>.</s> <s n=\"2.\"><b>to fall down at one's feet</b>, <b>fall prostrate before</b>: absol., seq. <g>πρός</g>, <r v=\"Mark.7.25\"></r>; c. dat. pers., <r v=\"Mark.3.11\"></r> <r v=\"Mark.5.33\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"Luke.8.47\"></r>, <r v=\"Acts.16.29\"></r>; <g>τ. γόνασιν</g>, <r v=\"Luke.5.8\"></r>.†</s>"},"G4364":{"l":"προσποιέω","o":1,"ar":"<f><o>προσ-ποιέω</o>، <g>-ῶ</g>،</f> <s><b>نقل إلى</b>، <b>أضاف</b> أو <b>ألحق بـ</b>. الصيغة الوسطى، <b>أخذ لنفسه</b>، <b>ادّعى</b>؛ ومن ثم <b>تظاهر</b>؛ مع المصدر، <b>تظاهر بأنه</b>: <r v=\"Luke.24.28\"></r>.†</s>","en":"<f><o>προσ-ποιέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.21.13\"></r> (<r v=\"1Sam.21.14\"></r>) (<h n=\"H1984\">הלל</h> hithpo.), <r v=\"Job.19.14\"></r>, <r v=\"Sir.31.30\"></r>, <r v=\"Sus.1.11\"></r>*;]</e> </et> <s><b>to make over to</b>, <b>add</b> or <b>attach to</b>. Mid., <b>to take to oneself</b>, <b>claim</b>; hence, <b>to pretend</b>; c. inf. (cf. Xen., <i>Anab.</i>, iv, 3, 20), <b>to make as if</b>: <r v=\"Luke.24.28\"></r>.†</s>"},"G4345":{"l":"προσκληρόω","o":1,"ar":"<f>*† <o>προσ-κληρόω</o>، <g>-ῶ</g>،</f> <s><b>خصّص لـ</b>، <b>عيّن بالقرعة</b>؛ المبني للمجهول (لكن ربما بمعنى الصيغة الوسطى، كما في الترجمات الإنجليزية: <i>انضمّوا إلى</i>، وكذلك في السريانية): <r v=\"Acts.17.4\"></r>.†</s>","en":"<f>*† <o>προσ-κληρόω</o>, <g>-ῶ</g>,</f> <s><b>to allot to</b>, <b>assign to by lot</b>; pass. (but perh. as mid., EV, <i>consorted with</i>, so Syr.): <r v=\"Acts.17.4\"></r> (for exx., v, Cremer, 749).†</s>"},"G4358":{"l":"προσορμίζω","o":1,"ar":"<f>* <o>προσ-ορμίζω</o></f> <s><b>أرسى</b> السفينة <b>عند</b>؛ وعادةً في الصيغة الوسطى، <b>رسا قرب</b>، وكذلك المبني للمجهول عند الكتّاب المتأخرين: <r v=\"Mark.6.53\"></r>.†</s>","en":"<f>* <o>προσ-ορμίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὅρμος</g>, <i>an anchorage</i>),</e> </et> <s><b>to bring</b> a ship <b>to anchor at</b>; usually in mid., <b>to come to anchor near</b>, and so pass. in late writers (Ael., Dio Cass.): <r v=\"Mark.6.53\"></r>.†</s>"},"G4399":{"l":"προφθάνω","o":1,"ar":"<f><o>προ-φθάνω</o>،</f> <s>مع اسم الفاعل (لكن الأكثر شيوعًا الفعل البسيط <g>φθάνω</g>، انظره)، <b>سبق</b>: <r v=\"Matt.17.25\"></r>.†</s>","en":"<f><o>προ-φθάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6923\">קדם</h> pi.;]</e> </et> <s>c. ptcp. (as in cl., but more freq. the simple <g>φθάνω</g>, q.v.), <b>to anticipate</b>: <r v=\"Matt.17.25\"></r>.†</s>"},"G4321":{"l":"προσαναλίσκω","o":1,"ar":"<f>* <o>προσ-αναλίσκω</o>،</f> <s><b>أنفق فوق ذلك</b>: <r v=\"Luke.8.43\"></r>.†</s>","en":"<f>* <o>προσ-αναλίσκω</o>,</f> <s><b>to spend besides</b>: <r v=\"Luke.8.43\"></r> (WH, R, mg., om.).†</s>"},"G4371":{"l":"προσφάγιον","o":1,"ar":"<f>*† <o>προσφάγιον</o>، <g>-ου, τό</g></f> <s>صيغة هلنستية لـ<g>ὄψον</g> (انظر تحت مدخل <g>ὀψάριον</g>)، <b>إدام</b> أو <b>طعام شهيّ</b> (خاصةً <i>السمك المطبوخ</i>)، يؤكل مع الخبز: <r v=\"John.21.5\"></r> (أي: <i>أعندكم شيء من السمك؟</i>).†</s>","en":"<f>*† <o>προσφάγιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>φαγεῖν</g>),</e> </et> <s>Hellenistic for <g>ὄψον</g> (v.s. <g>ὀψάριον</g>), <b>a relish</b> or <b>dainty</b> (esp. <i>cooked fish</i>), to be eaten with bread: <r v=\"John.21.5\"></r> (<i>have ye taken any fish</i>, Field, <i>Notes</i>, 109; Abbott, <i>Essays</i>, 105; cf. M, <i>Pr.</i>, 170<i>n</i>; MM, <i>Exp.</i>, xxi).†</s>"},"G4389":{"l":"προτρέπω","o":1,"ar":"<f>** <o>προ-τρέπω</o>،</f> <s><b>دفع إلى الأمام</b>، <b>حثّ</b>، <b>أقنع</b>. الصيغة الوسطى بالمعنى نفسه (كما في الكلاسيكية أيضًا): <r v=\"Acts.18.27\"></r>.†</s>","en":"<f>** <o>προ-τρέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.14.18\"></r>, <r v=\"2Macc.11.7\"></r>, <r v=\"4Macc.12.7\"></r> <r v=\"4Macc.15.12\"></r> <r v=\"4Macc.16.13\"></r>*;]</e> </et> <s><b>to urge forwards</b>, <b>exhort</b>, <b>persuade</b>. Mid., in same sense (as also in cl.): <r v=\"Acts.18.27\"></r>.†</s>"},"G4304":{"l":"προμελετάω","o":1,"ar":"<f>* <o>προ-μελετάω</o>، <g>-ῶ</g>،</f> <s><b>اهتمّ من قبل، أعدّ مسبقًا</b>: <r v=\"Luke.21.14\"></r>.†</s>","en":"<f>* <o>προ-μελετάω</o>, <g>-ῶ</g>,</f> <s><b>to premeditate</b>: <r v=\"Luke.21.14\"></r>.†</s>"},"G4377":{"l":"προσφωνέω","o":7,"ar":"<f><o>προσ-φωνέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>خاطب</b>، <b>نادى</b>؛ في الكلاسيكية: مع منصوب الشخص، ومع منصوبين (قارن <r v=\"2Macc.15.15\"></r>)؛ ومطلقًا: <r v=\"Acts.21.40\"></r>. وعند الكتّاب المتأخرين: مع القابل للشخص: <r v=\"Matt.11.16\"></r>، <r v=\"Luke.7.32\"></r> <r v=\"Luke.13.12\"></r> <r v=\"Luke.23.20\"></r>، <r v=\"Acts.22.2\"></r>.</s> <s n=\"2.\"><b>دعا</b>، <b>استدعى</b>: مع المنصوب (كما في الكلاسيكية)، <r v=\"Luke.6.13\"></r>.†</s>","en":"<f><o>προσ-φωνέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.2.21\"></r> <r v=\"1Esd.6.6\"></r>, <r v=\"1Esd.6.22\"></r>, <r v=\"2Macc.15.15\"></r>*;]</e> </et> <s n=\"1.\"><b>to address</b>, <b>call to</b>; in cl., c. acc. pers., c. dupl. acc. (cf. <r v=\"2Macc.15.15\"></r>); absol. (Hom., <i>Od.</i>, v, 159, al.): <r v=\"Acts.21.40\"></r>. In late writers, c. dat. pers.: <r v=\"Matt.11.16\"></r>, <r v=\"Luke.7.32\"></r> <r v=\"Luke.13.12\"></r> <r v=\"Luke.23.20\"></r>, <r v=\"Acts.22.2\"></r>.</s> <s n=\"2.\"><b>to call by name</b>, <b>summon</b>: c. acc. (as in cl.), <r v=\"Luke.6.13\"></r>.†</s>"},"G4366":{"l":"προσρήγνυμι","o":2,"ar":"<f>**† <o>προσ-ρήγνυμι</o>،</f> <s><b>صدم</b>، <b>ارتطم بـ</b>؛ <s n=\"(a)\">عند الكتّاب المتأخرين: متعدٍّ؛</s> <s n=\"(b)\">لازم، مع القابل: <r v=\"Luke.6.48\"></r>، <r v=\"Luke.6.49\"></r> (قارن <g>προσπίπτω</g>).†</s> </s>","en":"<f>**† <o>προσ-ρήγνυμι</o>,</f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Ps.2.9\"></r>*;]</e> </et> <s><b>to break against</b>, <b>dash against</b>; <s n=\"(a)\">trans. (<g>παιδία πέτραις</g>, FlJ, <i>Ant.</i>, ix, 4, 6);</s> <s n=\"(b)\">intrans., c. dat.: <r v=\"Luke.6.48\"></r>, <r v=\"Luke.6.49\"></r> (cf. <g>προσπίπτω</g>).†</s> </s>"},"G4370":{"l":"προστρέχω","o":3,"ar":"<f><o>προσ-τρέχω</o>،</f> <s><b>ركض إلى</b>: <r v=\"Mark.9.15\"></r> <r v=\"Mark.10.17\"></r>، <r v=\"Acts.8.30\"></r>.†</s>","en":"<f><o>προσ-τρέχω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7323\">רוּץ</h>;]</e> </et> <s><b>to run to</b>: <r v=\"Mark.9.15\"></r> <r v=\"Mark.10.17\"></r>, <r v=\"Acts.8.30\"></r>.†</s>"},"G4344":{"l":"προσκεφάλαιον","o":1,"ar":"<f><o>προσ-κεφάλαιον</o>، <g>-ου, τό</g>،</f> <s><b>وسادة</b>، <b>مخدّة</b>: <r v=\"Mark.4.38\"></r>.†</s>","en":"<f><o>προσ-κεφάλαιον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.13.18\"></r>, <r v=\"Ezek.13.20\"></r> (<h n=\"H3704\">כֶּסֶת</h>), <r v=\"1Esd.3.8\"></r>*;]</e> </et> <s><b>a pillow</b>, <b>cushion</b>: <r v=\"Mark.4.38\"></r>.†</s>"},"G4362":{"l":"προσπήγνυμι","o":1,"ar":"<f>* <o>προσ-πήγνυμι</o>،</f> <s><b>ثبّت في</b>: مطلقًا، <b>صلب</b>، <r v=\"Acts.2.23\"></r>.†</s>","en":"<f>* <o>προσ-πήγνυμι</o>,</f> <s><b>to fasten to</b>: absol., <b>to crucify</b>, <r v=\"Acts.2.23\"></r>.†</s>"},"G4305":{"l":"προμεριμνάω","o":1,"ar":"<f>*† <o>προ-μεριμνάω</o>، <g>-ῶ</g>،</f> <s><b>اهتمّ من قبل</b>: <r v=\"Mark.13.11\"></r>.†</s>","en":"<f>*† <o>προ-μεριμνάω</o>, <g>-ῶ</g>,</f> <s><b>to be anxious beforehand</b>: <r v=\"Mark.13.11\"></r>.†</s>"},"G4390":{"l":"προτρέχω","o":2,"ar":"<f><o>προ-τρέχω</o>،</f> <s n=\"1.\"><b>ركض إلى الأمام</b>.</s> <s n=\"2.\"><b>سبق راكضًا</b>، <b>تقدّم مسرعًا</b>: <r v=\"John.20.4\"></r>؛ يليه <g>εἰς τὸ ἔμπροσθεν</g>، <r v=\"Luke.19.4\"></r>.†</s>","en":"<f><o>προ-τρέχω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.8.11\"></r> (<h n=\"H6440\">לִפְנֵי</h> <h n=\"H7323\">רוּץ</h>), <r v=\"Job.41.13\"></r> (<r v=\"Job.41.14\"></r>) A (<h n=\"H1750\">דּוּץ</h>), <r v=\"Tob.11.3\"></r> (seq. <g>ἔμπροσθεν</g>), <r v=\"1Macc.16.21\"></r>*;]</e> </et> <s n=\"1.\"><b>to run forward</b>.</s> <s n=\"2.\"><b>to run on</b>, <b>run in advance</b>: <r v=\"John.20.4\"></r>; seq. <g>εἰς τὸ ἔμπροσθεν</g>, <r v=\"Luke.19.4\"></r>.†</s>"},"G4329":{"l":"προσδοκία","o":2,"ar":"<f><o>προσδοκία</o>، <g>-ας, ἡ</g></f> <s><b>انتظار، توقّع</b>: مع المضاف إليه المفعولي، <r v=\"Luke.21.26\"></r>؛ مع المضاف إليه الفاعلي، <r v=\"Acts.12.11\"></r>.†</s>","en":"<f><o>προσδοκία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσδοκάω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.49.10\"></r> (<h n=\"H3349\">יִקְהָה</h>), <r v=\"Ps.119.116\"></r> (<h n=\"H7664\">שֵׂבֶר</h>), <r v=\"Wis.17.13\"></r>, <r v=\"Sir.40.2\"></r>, al.;]</e> </et> <s><b>expectation</b>: c. gen. obj., <r v=\"Luke.21.26\"></r>; c. gen. subjc., <r v=\"Acts.12.11\"></r>.†</s>"},"G4315":{"l":"προσάββατον","o":1,"ar":"<f>† <o>προ-σάββατον</o>، <g>-ου, τό</g>،</f> <s><b>اليوم الذي قبل السبت</b>: <r v=\"Mark.15.42\"></r>.†</s>","en":"<f>† <o>προ-σάββατον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.92.1\"></r>, <h>א</h> (<h n=\"H7676\">שַׁבָּת</h>) <r v=\"Ps.93.1\"></r>, <r v=\"Jdt.8.6\"></r>*;]</e> </et> <s><b>the day before the Sabbath</b>: <r v=\"Mark.15.42\"></r> (L, Tr., txt., <g>πρὸς σ.</g>).†</s>"},"G4353":{"l":"προσκυνητήν","o":1,"ar":"<f>*† <o>προσ-κυνητής</o>، <g>-οῦ, ὁ</g></f> <s><b>ساجد، عابد</b>: <r v=\"John.4.23\"></r>.†</s>","en":"<f>*† <o>προσ-κυνητής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσκυνέω</g>),</e> </et> <s><b>a worshipper</b>: <r v=\"John.4.23\"></r>.†</s>"}});A.got[43]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});